// Package order provides an insertion-ordered map that preserves duplicate keys.
package order

// MapItem is a single key/value pair of a MapSlice.
type MapItem struct {
	Key interface{}
	Val interface{}
}

// MapSlice is an ordered list of key/value pairs. Duplicate keys are allowed.
type MapSlice []MapItem

// Get returns the value for key k.
func (m MapSlice) Get(k interface{}) (interface{}, bool) {
	for _, it := range m {
		if keyEq(it.Key, k) {
			return it.Val, true
		}
	}
	return nil, false
}

func keyEq(a, b interface{}) bool {
	return a == b
}
