{"command": "cat > /workspace/src/jsonw.go <<'EOF'
package main

import (
	"bytes"
	"encoding/json"
	"math"
	"strconv"
	"time"

	"./order"
)

// encOpts controls JSON encoding.
type encOpts struct {
	indent     bool
	escapeHTML bool
	noInf      bool
}

var hexDigits = "0123456789abcdef"

// jsonSafe reports whether byte b needs no escaping when HTML escaping is off.
func jsonSafe(b byte) bool {
	if b < 0x20 {
		return false
	}
	return b != '"' && b != '\\'
}

// htmlSafe reports whether byte b needs no escaping when HTML escaping is on.
func htmlSafe(b byte) bool {
	switch b {
	case '"', '\\', '<', '>', '&':
		return false
	}
	if b < 0x20 {
		return false
	}
	return true
}

// writeJSONString writes a JSON string literal.
func writeJSONString(buf *bytes.Buffer, s string, escapeHTML bool) {
	buf.WriteByte('"')
	start := 0
	for i := 0; i < len(s); {
		if b := s[i]; b < 0x80 {
			safe := jsonSafe(b)
			if escapeHTML {
				safe = htmlSafe(b)
			}
			if safe {
				i++
				continue
			}
			if start < i {
				buf.WriteString(s[start:i])
			}
			buf.WriteByte('\\')
			switch b {
			case '\\', '"':
				buf.WriteByte(b)
			case '\n':
				buf.WriteByte('n')
			case '\r':
				buf.WriteByte('r')
			case '\t':
				buf.WriteByte('t')
			default:
				buf.WriteString(`u00`)
				buf.WriteByte(hexDigits[b>>4])
				buf.WriteByte(hexDigits[b&0xf])
			}
			i++
			start = i
			continue
		}
		c, size := utf8DecodeRuneInString(s[i:])
		if c == 0xfffd && size == 1 {
			if start < i {
				buf.WriteString(s[start:i])
			}
			buf.WriteString(`\ufffd`)
			i += size
			start = i
			continue
		}
		if c == 0x2028 || c == 0x2029 {
			if start < i {
				buf.WriteString(s[start:i])
			}
			buf.WriteString(`\u202`)
			buf.WriteByte(hexDigits[c&0xf])
			i += size
			start = i
			continue
		}
		i += size
	}
	if start < len(s) {
		buf.WriteString(s[start:])
	}
	buf.WriteByte('"')
}

// formatJSONFloat mimics Go's json encoder float formatting (ES6 style).
func formatJSONFloat(f float64) string {
	abs := math.Abs(f)
	format := byte('f')
	if abs != 0 && (abs < 1e-6 || abs >= 1e21) {
		format = 'e'
	}
	s := strconv.FormatFloat(f, format, -1, 64)
	if format == 'e' {
		// clean up e-09 to e-9
		n := len(s)
		if n >= 4 && s[n-4] == 'e' && s[n-3] == '-' && s[n-2] == '0' {
			s = s[:n-2] + s[n-1:]
		}
	}
	return s
}

// encodeJSON encodes v as JSON.
func encodeJSON(v interface{}, o encOpts) []byte {
	buf := &bytes.Buffer{}
	if o.indent {
		writeJSONIndent(buf, v, 0, o)
		buf.WriteByte('\n')
	} else {
		writeJSONCompact(buf, v, o)
		buf.WriteByte('\n')
	}
	return buf.Bytes()
}

func writeJSONCompact(buf *bytes.Buffer, v interface{}, o encOpts) {
	switch t := v.(type) {
	case nil:
		buf.WriteString("null")
	case bool:
		if t {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case string:
		writeJSONString(buf, t, o.escapeHTML)
	case int64:
		buf.WriteString(strconv.FormatInt(t, 10))
	case uint64:
		buf.WriteString(strconv.FormatUint(t, 10))
	case float64:
		writeJSONFloat(buf, t, o)
	case time.Time:
