package main

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"./order"
)

// node kinds
const (
	nScalar = iota
	nSeq
	nMap
	nAlias
)

// scalar styles
const (
	stPlain = iota
	stSingle
	stDouble
	stLiteral
	stFolded
)

type node struct {
	kind   int
	tag    string // explicit tag, "" if none
	value  string // scalar text
	style  int
	items  []*node
	pairs  [][2]*node // key, value
	alias  *node
	line   int // 0-based line of the node start
}

type parser struct {
	src     []byte
	pos     int
	line    int // 0-based
	col     int // 0-based
	anchors map[string]*node
	streamEnd bool
}

func (p *parser) atEnd() bool { return p.pos >= len(p.src) }

func (p *parser) peek() byte {
	if p.atEnd() {
		return 0
	}
	return p.src[p.pos]
}

func (p *parser) peekAt(n int) byte {
	if p.pos+n >= len(p.src) {
		return 0
	}
	return p.src[p.pos+n]
}

func (p *parser) advance() {
	if p.atEnd() {
		return
	}
	if p.src[p.pos] == '\n' {
		p.line++
		p.col = 0
	} else {
		p.col++
	}
	p.pos++
}

func (p *parser) advanceN(n int) {
	for i := 0; i < n; i++ {
		p.advance()
	}
}

func (p *parser) errf(format string, args ...interface{}) error {
	return fmt.Errorf("yaml: line %d: %s", p.line, fmt.Sprintf(format, args...))
}

// skipBlankLines skips whitespace, comments and line breaks, stopping at the
// next content character (or EOF).
func (p *parser) skipToContent() {
	for !p.atEnd() {
		c := p.peek()
		if c == ' ' || c == '\t' {
			p.advance()
			continue
		}
		if c == '\n' {
			p.advance()
			continue
		}
		if c == '\r' && p.peekAt(1) == '\n' {
			p.advance()
			continue
		}
		if c == '#' {
			for !p.atEnd() && p.peek() != '\n' {
				p.advance()
			}
			continue
		}
		return
	}
}

func isBlankz(c byte) bool { return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == 0 }

// parseYAML parses the first document of src into an ordered value.
func parseYAML(src []byte) (interface{}, error) {
	p := &parser{src: src, line: 0, col: 0, anchors: map[string]*node{}}
	return p.parseDocument()
}

// parseYAMLNodes parses all documents (used by the emitter validator).
func parseYAMLText(src []byte) (interface{}, error) {
	p := &parser{src: src, anchors: map[string]*node{}}
	return p.parseDocument()
}

func (p *parser) parseDocument() (interface{}, error) {
	p.skipToContent()
	// document start indicator
	if p.hasPrefix("---") && isBlankz(p.peekAt(3)) {
		p.advanceN(3)
		p.skipSpacesOnLine()
		// check for an empty document
		if p.atEnd() {
			return nil, nil
		}
		c := p.peek()
		if c == '\n' {
			// content on the following lines
			return p.parseBlockNode(-1)
		}
		// inline content
		n, err := p.parseInlineNode(-1)
		if err != nil {
			return nil, err
		}
		return nodeToValue(n, p)
	}
	n, err := p.parseBlockNode(-1)
	if err != nil {
		return nil, err
	}
	return nodeToValue(n, p)
}

func (p *parser) hasPrefix(s string) bool {
	if p.pos+len(s) > len(p.src) {
		return false
	}
	return string(p.src[p.pos:p.pos+len(s)]) == s
}

func (p *parser) skipSpacesOnLine() {
	for !p.atEnd() {
		c := p.peek()
		if c == ' ' || c == '\t' {
			p.advance()
			continue
		}
		return
	}
}

// parseBlockNode parses a node at the current position, which must be more
// indented than parentIndent. Returns nil for an empty node.
func (p *parser) parseBlockNode(parentIndent int) (*node, error) {
	p.skipToContent()
	if p.atEnd() {
		return &node{kind: nScalar, value: "", style: stPlain, tag: "!!null"}, nil
	}
	indent := p.col
	if indent <= parentIndent {
		// empty node
		return &node{kind: nScalar, value: "", style: stPlain, tag: "!!null"}, nil
	}
	// document end
	if p.hasPrefix("...") && isBlankz(p.peekAt(3)) {
		return &node{kind: nScalar, value: "", style: stPlain, tag: "!!null"}, nil
	}
	if p.hasPrefix("---") && isBlankz(p.peekAt(3)) {
		return &node{kind: nScalar, value: "", style: stPlain, tag: "!!null"}, nil
	}
	// block sequence
	if p.peek() == '-' && isBlankz(p.peekAt(1)) {
		return p.parseBlockSequence(indent)
	}
	// properties (anchor/tag) or scalar or mapping
	return p.parseBlockContent(indent)
}

// parseBlockContent handles properties, scalars and mappings at the given indent.
func (p *parser) parseBlockContent(indent int) (*node, error) {
	var anchor string
	var tag string
	for {
		if p.peek() == '&' {
			a, err := p.scanAnchorName()
			if err != nil {
				return nil, err
			}
			anchor = a
			p.skipSpacesOnLine()
			continue
		}
		if p.peek() == '!' {
			t, err := p.scanTag()
			if err != nil {
				return nil, err
			}
			tag = t
			p.skipSpacesOnLine()
			continue
		}
		break
	}
	p.skipToContent()
	// block scalar
	if p.peek() == '|' || p.peek() == '>' {
		n, err := p.parseBlockScalar(p.col, tag)
		if err != nil {
			return nil, err
		}
		if anchor != "" {
			p.anchors[anchor] = n
		}
		return n, nil
	}
	if p.peek() == '&' {
		// alias as a value
		p.advance()
		name, err := p.scanName()
		if err != nil {
			return nil, err
		}
		n := &node{kind: nAlias, value: name}
		if anchor != "" {
			p.anchors[anchor] = n
		}
		return n, nil
	}
	if p.peek() == '*' {
		p.advance()
		name, err := p.scanName()
		if err != nil {
			return nil, err
		}
		return &node{kind: nAlias, value: name}, nil
	}
	if p.peek() == '[' || p.peek() == '{' {
		n, err := p.parseFlowNode()
		if err != nil {
			return nil, err
		}
		if anchor != "" {
			p.anchors[anchor] = n
		}
		return n, nil
	}
	// try to read a key: scan a scalar, then check for ':'
	save := *p
	keyNode, err := p.scanScalarNode(false)
	if err != nil {
		return nil, err
	}
	p.skipSpacesOnLine()
	if p.peek() == ':' && (p.peekAt(1) == ' ' || p.peekAt(1) == '\t' || p.peekAt(1) == '\n' || p.atEndOfLine() && p.peekAt(1) == 0 || p.peekAt(1) == '\r') {
		// block mapping
		p.advance()
		return p.parseBlockMapping(indent, keyNode, anchor, tag, &save)
	}
	// not a mapping: restore and parse a scalar value (possibly multi-line)
	*p = save
	if tag != "" || anchor != "" {
		n, err := p.parseValueWithProps(tag, anchor, indent)
		if err != nil {
			return nil, err
		}
		return n, nil
	}
	n, err := p.parseScalarValue(indent)
	if err != nil {
		return nil, err
	}
	return n, nil
}

func (p *parser) atEndOfLine() bool {
	if p.pos+1 >= len(p.src) {
		return true
	}
	return false
}

func (p *parser) parseBlockMapping(indent int, firstKey *node, anchor, tag string, save *parser) (*node, error) {
	n := &node{kind: nMap}
	first := true
	var keyNode *node
	var keyAnchor, keyTag string
	for {
		if first {
			keyNode = firstKey
			keyAnchor, keyTag = anchor, tag
			first = false
			// parse the value
			val, err := p.parseMappingValue(indent)
			if err != nil {
				return nil, err
			}
			n.pairs = append(n.pairs, [2]*node{keyNode, val})
			if keyAnchor != "" {
				p.anchors[keyAnchor] = keyNode
			}
			continue
		}
		// next key
		p.skipToContent()
		if p.atEnd() {
			break
		}
		if p.hasPrefix("...") && isBlankz(p.peekAt(3)) {
			break
		}
		if p.hasPrefix("---") && isBlankz(p.peekAt(3)) {
			break
		}
		if p.col < indent {
			break
		}
		if p.col > indent {
			// could be a continuation of a previous multi-line scalar; not supported here
			break
		}
		if p.peek() == '#' {
			p.skipComment()
			continue
		}
		if p.peek() == '-' && isBlankz(p.peekAt(1)) {
			// indentless sequence? handled by the value parser; shouldn't happen here
			break
		}
		// properties
		var ka, kt string
		for {
			if p.peek() == '&' {
				a, err := p.scanAnchorName()
				if err != nil {
					return nil, err
				}
				ka = a
				p.skipSpacesOnLine()
				continue
			}
			if p.peek() == '!' {
				t, err := p.scanTag()
				if err != nil {
					return nil, err
				}
				kt = t
				p.skipSpacesOnLine()
				continue
			}
			break
		}
		keyNode, err := p.scanScalarNode(false)
		if err != nil {
			return nil, err
		}
		p.skipSpacesOnLine()
		if p.peek() != ':' {
			return nil, p.errf("could not find expected ':'")
		}
		p.advance()
		val, err := p.parseMappingValue(indent)
		if err != nil {
			return nil, err
		}
		n.pairs = append(n.pairs, [2]*node{keyNode, val})
		if ka != "" {
			p.anchors[ka] = keyNode
		}
		_ = kt
	}
	if anchor != "" {
		p.anchors[anchor] = n
	}
	return n, nil
}

func (p *parser) skipComment() {
	for !p.atEnd() && p.peek() != '\n' {
		p.advance()
	}
}

// parseMappingValue parses the value after a ':' at the given mapping indent.
func (p *parser) parseMappingValue(indent int) (*node, error) {
	p.skipSpacesOnLine()
	// comment on the same line
	if p.peek() == '#' {
		p.skipComment()
	}
	if !p.atEnd() && p.peek() != '\n' {
		// inline value
		if p.peek() == '[' || p.peek() == '{' {
			return p.parseFlowNode()
		}
		if p.peek() == '&' {
			p.advance()
			name, err := p.scanName()
			if err != nil {
				return nil, err
			}
			return &node{kind: nAlias, value: name}, nil
		}
		if p.peek() == '*' {
			p.advance()
			name, err := p.scanName()
			if err != nil {
				return nil, err
			}
			return &node{kind: nAlias, value: name}, nil
		}
		var tag string
		for {
			if p.peek() == '!' {
				t, err := p.scanTag()
				if err != nil {
					return nil, err
				}
				tag = t
				p.skipSpacesOnLine()
				continue
			}
			if p.peek() == '&' {
				p.advance()
				name, err := p.scanName()
				if err != nil {
					return nil, err
				}
				// anchor for an inline value
				n, err := p.parseInlineScalarValue(indent)
				if err != nil {
					return nil, err
				}
				p.anchors[name] = n
				return n, nil
			}
			break
		}
		if p.peek() == '|' || p.peek() == '>' {
			return p.parseBlockScalar(p.col, tag)
		}
		n, err := p.parseInlineScalarValue(indent)
		if err != nil {
			return nil, err
		}
		if tag != "" {
			n.tag = tag
		}
		return n, nil
	}
	// value on the following lines
	p.skipToContent()
	if p.atEnd() {
		return &node{kind: nScalar, value: "", style: stPlain, tag: "!!null"}, nil
	}
	if p.hasPrefix("...") && isBlankz(p.peekAt(3)) || p.hasPrefix("---") && isBlankz(p.peekAt(3)) {
		return &node{kind: nScalar, value: "", style: stPlain, tag: "!!null"}, nil
	}
	if p.col < indent {
		return &node{kind: nScalar, value: "", style: stPlain, tag: "!!null"}, nil
	}
	// indentless sequence
	if p.peek() == '-' && isBlankz(p.peekAt(1)) && p.col == indent {
		return p.parseBlockSequence(indent)
	}
	if p.col > indent {
		// properties
		var tag string
		for {
			if p.peek() == '&' {
				p.advance()
				name, err := p.scanName()
				if err != nil {
					return nil, err
				}
				p.skipSpacesOnLine()
				n, err := p.parseBlockNode(indent)
				if err != nil {
					return nil, err
				}
				p.anchors[name] = n
				return n, nil
			}
			if p.peek() == '!' {
				t, err := p.scanTag()
				if err != nil {
					return nil, err
				}
				tag = t
				p.skipSpacesOnLine()
				continue
			}
			break
		}
		if p.peek() == '*' {
			p.advance()
			name, err := p.scanName()
			if err != nil {
				return nil, err
			}
			return &node{kind: nAlias, value: name}, nil
		}
		if p.peek() == '|' || p.peek() == '>' {
			return p.parseBlockScalar(p.col, tag)
		}
		if p.peek() == '[' || p.peek() == '{' {
			return p.parseFlowNode()
		}
		// could be a mapping or a multi-line scalar
		return p.parseBlockNode(indent)
	}
	// same indent, non-sequence -> empty value
	return &node{kind: nScalar, value: "", style: stPlain, tag: "!!null"}, nil
}

// parseInlineScalarValue parses a scalar value on the current line, which may
// continue on the following lines.
func (p *parser) parseInlineScalarValue(indent int) (*node, error) {
	return p.scanScalarNode(true)
}

func (p *parser) parseValueWithProps(tag, anchor string, indent int) (*node, error) {
	if p.peek() == '|' || p.peek() == '>' {
		return p.parseBlockScalar(p.col, tag)
	}
	if p.peek() == '[' || p.peek() == '{' {
		return p.parseFlowNode()
	}
	if p.peek() == '*' {
		p.advance()
		name, err := p.scanName()
		if err != nil {
			return nil, err
		}
		return &node{kind: nAlias, value: name}, nil
	}
	n, err := p.scanScalarNode(true)
	if err != nil {
		return nil, err
	}
	if tag != "" {
		n.tag = tag
	}
	if anchor != "" {
		p.anchors[anchor] = n
	}
	return n, nil
}

// parseScalarValue parses a plain or quoted scalar that may span lines.
func (p *parser) parseScalarValue(indent int) (*node, error) {
	return p.scanScalarNode(true)
}

// scanName scans an anchor/alias name.
func (p *parser) scanName() (string, error) {
	start := p.pos
	for !p.atEnd() {
		c := p.peek()
		if isBlankz(c) || c == ',' || c == '[' || c == ']' || c == '{' || c == '}' {
			break
		}
		p.advance()
	}
	if p.pos == start {
		return "", p.errf("did not find expected alphabetic or numeric character")
	}
	return string(p.src[start:p.pos]), nil
}

func (p *parser) scanAnchorName() (string, error) {
	p.advance() // &
	return p.scanName()
}

// scanTag scans a tag and returns the full tag string.
func (p *parser) scanTag() (string, error) {
	start := p.pos
	p.advance() // !
	if p.peek() == '!' {
		// shorthand: !!suffix
		p.advance()
		start2 := p.pos
		for !p.atEnd() {
			c := p.peek()
			if isBlankz(c) || c == ',' || c == '[' || c == ']' || c == '{' || c == '}' {
				break
			}
			p.advance()
		}
		if p.pos == start2 {
			return "", p.errf("did not find expected tag URI")
		}
		return "tag:yaml.org,2002:" + string(p.src[start2:p.pos]), nil
	}
	if p.peek() == '<' {
		// verbatim tag
		p.advance()
		start2 := p.pos
		for !p.atEnd() && p.peek() != '>' {
			p.advance()
		}
		if p.atEnd() {
			return "", p.errf("did not find expected '>'")
		}
		s := string(p.src[start2:p.pos])
		p.advance() // >
		return s, nil
	}
	// local tag or shorthand with a single !
	start2 := p.pos
	for !p.atEnd() {
		c := p.peek()
		if isBlankz(c) || c == ',' || c == '[' || c == ']' || c == '{' || c == '}' {
			break
		}
		p.advance()
	}
	rest := string(p.src[start2:p.pos])
	if rest == "" {
		return "tag:yaml.org,2002:", nil
	}
	return "!" + rest, nil
}

func shortTag(tag string) string {
	if strings.HasPrefix(tag, "tag:yaml.org,2002:") {
		return "!!" + tag[len("tag:yaml.org,2002:"):]
	}
	return tag
}

// scanScalarNode scans a scalar starting at the current position. If multiline
// is true a plain scalar may continue over the following lines.
func (p *parser) scanScalarNode(multiline bool) (*node, error) {
	switch p.peek() {
	case '\'':
		return p.scanSingleQuoted()
	case '"':
		return p.scanDoubleQuoted()
	case '|':
		return p.parseBlockScalar(p.col, "")
	case '>':
		return p.parseBlockScalar(p.col, "")
	}
	return p.scanPlainScalar(multiline)
}

func (p *parser) scanSingleQuoted() (*node, error) {
	p.advance() // '
	var b strings.Builder
	for {
		if p.atEnd() {
			return nil, p.errf("found unexpected end of stream")
		}
		c := p.peek()
		if c == '\'' {
			if p.peekAt(1) == '\'' {
				b.WriteByte('\'')
				p.advanceN(2)
				continue
			}
			p.advance()
			break
		}
		if c == '\n' {
			// fold: skip leading spaces on the next line
			p.advance()
			b.WriteByte('\n')
			// strip the indentation of the continuation line
			for !p.atEnd() && p.peek() == ' ' {
				p.advance()
			}
			continue
		}
		if c == '\r' && p.peekAt(1) == '\n' {
			p.advance()
			continue
		}
		b.WriteByte(c)
		p.advance()
	}
	return &node{kind: nScalar, value: b.String(), style: stSingle, tag: "!!str"}, nil
}

func (p *parser) scanDoubleQuoted() (*node, error) {
	p.advance() // "
	var b strings.Builder
	for {
		if p.atEnd() {
			return nil, p.errf("found unexpected end of stream")
		}
		c := p.peek()
		if c == '"' {
			p.advance()
			break
		}
		if c == '\\' {
			p.advance()
			if p.atEnd() {
				return nil, p.errf("found unexpected end of stream")
			}
			e := p.peek()
			switch e {
			case '0':
				b.WriteByte(0)
				p.advance()
			case 'a':
				b.WriteByte(7)
				p.advance()
			case 'b':
				b.WriteByte(8)
				p.advance()
			case 't', '\t':
				b.WriteByte('\t')
				p.advance()
			case 'n':
				b.WriteByte('\n')
				p.advance()
			case 'v':
				b.WriteByte(11)
				p.advance()
			case 'f':
				b.WriteByte(12)
				p.advance()
			case 'r':
				b.WriteByte('\r')
				p.advance()
			case 'e':
				b.WriteByte(0x1b)
				p.advance()
			case ' ':
				b.WriteByte(' ')
				p.advance()
			case '"':
				b.WriteByte('"')
				p.advance()
			case '/':
				b.WriteByte('/')
				p.advance()
			case '\\':
				b.WriteByte('\\')
				p.advance()
			case 'N':
				b.WriteString("\u0085")
				p.advance()
			case '_':
				b.WriteString("\u00a0")
				p.advance()
			case 'L':
				b.WriteString("\u2028")
				p.advance()
			case 'P':
				b.WriteString("\u2029")
				p.advance()
			case 'x':
				p.advance()
				h, err := p.scanHex(2)
				if err != nil {
					return nil, err
				}
				b.WriteRune(rune(int(h)))
			case 'u':
				p.advance()
				h, err := p.scanHex(4)
				if err != nil {
					return nil, err
				}
				if h >= 0xD800 && h <= 0xDFFF {
					return nil, errors.New("yaml: found invalid Unicode character escape code")
				}
				b.WriteRune(rune(int(h)))
			case 'U':
				p.advance()
				h, err := p.scanHex(8)
				if err != nil {
					return nil, err
				}
				if h >= 0xD800 && h <= 0xDFFF {
					return nil, errors.New("yaml: found invalid Unicode character escape code")
				}
				b.WriteRune(rune(int(h)))
			case '\n':
				// escaped line break: skip leading whitespace
				p.advance()
				for !p.atEnd() && (p.peek() == ' ' || p.peek() == '\t') {
					p.advance()
				}
			default:
				return nil, p.errf("found unknown escape character")
			}
			continue
		}
		if c == '\n' {
			p.advance()
			b.WriteByte('\n')
			for !p.atEnd() && p.peek() == ' ' {
				p.advance()
			}
			continue
		}
		if c == '\r' && p.peekAt(1) == '\n' {
			p.advance()
			continue
		}
		b.WriteByte(c)
		p.advance()
	}
	return &node{kind: nScalar, value: b.String(), style: stDouble, tag: "!!str"}, nil
}

func (p *parser) scanHex(n int) (int64, error) {
	var v int64
	for i := 0; i < n; i++ {
		c := p.peek()
		var d int64
		switch {
		case c >= '0' && c <= '9':
			d = int64(c - '0')
		case c >= 'a' && c <= 'f':
			d = int64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int64(c-'A') + 10
		default:
			return 0, errors.New("yaml: found invalid Unicode character escape code")
		}
		v = v*16 + d
		p.advance()
	}
	return v, nil
}

func rune(i int) rune {
	if i > 0x10FFFF {
		return 0xfffd
	}
	return rune(i)
}

// scanPlainScalar scans a plain scalar, possibly spanning lines.
func (p *parser) scanPlainScalar(multiline bool) (*node, error) {
	startLine := p.line
	var b strings.Builder
	pendingBreaks := 0
	first := true
	for {
		if p.atEnd() {
			break
		}
		c := p.peek()
		if c == '\n' || (c == '\r' && p.peekAt(1) == '\n') {
			// possible continuation
			if !multiline {
				break
			}
			// look ahead to the next line's indentation and content
			save := *p
			nl := p.line
			p.advance() // newline
			for !p.atEnd() && (p.peek() == ' ' || p.peek() == '\t') {
				p.advance()
			}
			if p.atEnd() || p.peek() == '\n' || p.peek() == '\r' {
				*p = save
				break
			}
			// check for document markers
			if p.hasPrefix("---") || p.hasPrefix("...") {
				if p.col == 0 {
					*p = save
					break
				}
			}
			if p.col <= 0 {
				*p = save
				break
			}
			// continuation line: check that it's not a new key
			if p.isKeyAhead() {
				*p = save
				break
			}
			if pendingBreaks == 0 && !first {
				// fold: previous line's trailing spaces are stripped; join with a space
			}
			pendingBreaks++
			if pendingBreaks == 1 {
				b.WriteByte(' ')
			} else {
				b.WriteByte('\n')
			}
			p.line = nl + 1
			p.col = 0
			for !p.atEnd() && (p.peek() == ' ' || p.peek() == '\t') {
				p.advance()
			}
			first = false
			continue
		}
		// stop indicators
		if c == ':' && isBlankz(p.peekAt(1)) {
			break
		}
		if c == '#' && p.col > 0 && isBlankzByte(p.src[p.pos-1]) {
			break
		}
		if c == ',' || c == '[' || c == ']' || c == '{' || c == '}' {
			break
		}
		b.WriteByte(c)
		p.advance()
		first = false
	}
	// trim trailing spaces
	v := strings.TrimRight(b.String(), " \t")
	n := &node{kind: nScalar, value: v, style: stPlain, line: startLine}
	return n, nil
}

func isBlankzByte(c byte) bool { return c == ' ' || c == '\t' || c == '\n' || c == '\r' }

// isKeyAhead reports whether the current line looks like a mapping key.
func (p *parser) isKeyAhead() bool {
	i := p.pos
	depth := 0
	for i < len(p.src) {
		c := p.src[i]
		if c == '\n' {
			return false
		}
		if c == ':' {
			if i+1 >= len(p.src) || p.src[i+1] == ' ' || p.src[i+1] == '\t' || p.src[i+1] == '\n' || p.src[i+1] == '\r' {
				return true
			}
		}
		if c == '#' {
			return false
		}
		i++
	}
	return false
}

// parseFlowNode parses a flow collection or scalar.
func (p *parser) parseFlowNode() (*node, error) {
	switch p.peek() {
	case '[':
		return p.parseFlowSeq()
	case '{':
		return p.parseFlowMap()
	}
	return p.scanScalarNode(false)
}

func (p *parser) skipFlowSpace() {
	for !p.atEnd() {
		c := p.peek()
		if c == ' ' || c == '\t' {
			p.advance()
			continue
		}
		if c == '\n' || (c == '\r' && p.peekAt(1) == '\n') {
			p.advance()
			continue
		}
		if c == '#' {
			p.skipComment()
			continue
		}
		return
	}
}

func (p *parser) parseFlowSeq() (*node, error) {
	p.advance() // [
	n := &node{kind: nSeq, style: stPlain}
	for {
		p.skipFlowSpace()
		if p.atEnd() {
			return nil, p.errf("did not find expected ',' or ']'")
		}
		if p.peek() == ']' {
			p.advance()
			return n, nil
		}
		item, err := p.parseFlowItem()
		if err != nil {
			return nil, err
		}
		n.items = append(n.items, item)
		p.skipFlowSpace()
		if p.atEnd() {
			return nil, p.errf("did not find expected ',' or ']'")
		}
		if p.peek() == ',' {
			p.advance()
			continue
		}
		if p.peek() == ']' {
			p.advance()
			return n, nil
		}
		return nil, p.errf("did not find expected ',' or ']'")
	}
}

func (p *parser) parseFlowItem() (*node, error) {
	// properties
	var tag string
	var anchor string
	for {
		if p.peek() == '&' {
			p.advance()
			name, err := p.scanName()
			if err != nil {
				return nil, err
			}
			anchor = name
			p.skipFlowSpace()
			continue
		}
		if p.peek() == '!' {
			t, err := p.scanTag()
			if err != nil {
				return nil, err
			}
			tag = t
			p.skipFlowSpace()
			continue
		}
		break
	}
	var n *node
	var err error
	switch p.peek() {
	case '[', '{':
		n, err = p.parseFlowNode()
		if err != nil {
			return nil, err
		}
	case '*':
		p.advance()
		name, err := p.scanName()
		if err != nil {
			return nil, err
		}
		n = &node{kind: nAlias, value: name}
	default:
		n, err = p.scanFlowScalar()
		if err != nil {
			return nil, err
		}
		// flow mapping key?
		save := *p
		p.skipFlowSpace()
		if p.peek() == ':' {
			p.advance()
			p.skipFlowSpace()
			var val *node
			if p.atEnd() || p.peek() == ',' || p.peek() == ']' || p.peek() == '}' {
				val = &node{kind: nScalar, value: "", style: stPlain, tag: "!!null"}
			} else {
				val, err = p.parseFlowItem()
				if err != nil {
					return nil, err
				}
			}
			m := &node{kind: nMap, pairs: [][2]*node{{n, val}}}
			if anchor != "" {
				p.anchors[anchor] = m
			}
			return m, nil
		}
		*p = save
	}
	if tag != "" {
		n.tag = tag
	}
	if anchor != "" {
		p.anchors[anchor] = n
	}
	return n, nil
}

func (p *parser) parseFlowMap() (*node, error) {
	p.advance() // {
	n := &node{kind: nMap, style: stPlain}
	for {
		p.skipFlowSpace()
		if p.atEnd() {
			return nil, p.errf("did not find expected ',' or '}'")
		}
		if p.peek() == '}' {
			p.advance()
			return n, nil
		}
		key, err := p.parseFlowItem()
		if err != nil {
			return nil, err
		}
		// key must be followed by ':'
		p.skipFlowSpace()
		if p.peek() != ':' {
			return nil, p.errf("could not find expected ':'")
		}
		p.advance()
		p.skipFlowSpace()
		var val *node
		if p.atEnd() || p.peek() == ',' || p.peek() == '}' {
			val = &node{kind: nScalar, value: "", style: stPlain, tag: "!!null"}
		} else {
			val, err = p.parseFlowItem()
			if err != nil {
				return nil, err
			}
		}
		n.pairs = append(n.pairs, [2]*node{key, val})
		p.skipFlowSpace()
		if p.atEnd() {
			return nil, p.errf("did not find expected ',' or '}'")
		}
		if p.peek() == ',' {
			p.advance()
			continue
		}
		if p.peek() == '}' {
			p.advance()
			return n, nil
		}
		return nil, p.errf("did not find expected ',' or '}'")
	}
}

// scanFlowScalar scans a plain scalar inside a flow collection.
func (p *parser) scanFlowScalar() (*node, error) {
	switch p.peek() {
	case '\'':
		return p.scanSingleQuoted()
	case '"':
		return p.scanDoubleQuoted()
	}
	var b strings.Builder
	for !p.atEnd() {
		c := p.peek()
		if c == ',' || c == '[' || c == ']' || c == '{' || c == '}' {
			break
		}
		if c == ':' && isBlankz(p.peekAt(1)) {
			break
		}
		if c == '#' && p.col > 0 && p.pos > 0 && isBlankzByte(p.src[p.pos-1]) {
			break
		}
		if c == '\n' {
			p.advance()
			b.WriteByte(' ')
			for !p.atEnd() && (p.peek() == ' ' || p.peek() == '\t') {
				p.advance()
			}
			continue
		}
		b.WriteByte(c)
		p.advance()
	}
	v := strings.TrimRight(b.String(), " \t")
	return &node{kind: nScalar, value: v, style: stPlain}, nil
}

// parseBlockScalar parses a literal or folded block scalar.
func (p *parser) parseBlockScalar(indicatorCol int, tag string) (*node, error) {
	style := stLiteral
	if p.peek() == '>' {
		style = stFolded
	}
	p.advance()
	// indentation indicator and chomping
	indentHint := 0
	chomp := byte(0)
	for {
		c := p.peek()
		if c >= '1' && c <= '9' {
			indentHint = int(c - '0')
			p.advance()
			continue
		}
		if c == '+' || c == '-' {
			chomp = c
			p.advance()
			continue
		}
		break
	}
	// skip to end of line
	for !p.atEnd() {
		c := p.peek()
		if c == ' ' || c == '\t' {
			p.advance()
			continue
		}
		break
	}
	if !p.atEnd() && p.peek() == '#' {
		p.skipComment()
	}
	if !p.atEnd() && p.peek() == '\n' {
		p.advance()
	} else if !p.atEnd() && p.peek() == '\r' && p.peekAt(1) == '\n' {
		p.advanceN(2)
	} else if !p.atEnd() {
		return nil, p.errf("did not find expected comment or line break")
	}
	// determine the indentation
	var detectIndent int
	if indentHint > 0 {
		detectIndent = indicatorCol + indentHint
	} else {
		detectIndent = -1
	}
	var b strings.Builder
	breaks := 0
	sawContent := false
	for {
		if p.atEnd() {
			break
		}
		// measure the indentation of this line
		lineStart := p.pos
		ind := 0
		for !p.atEnd() && p.peek() == ' ' {
			ind++
			p.advance()
		}
		if p.atEnd() {
			if ind > 0 {
				breaks++
			}
			break
		}
		c := p.peek()
		if c == '\n' || (c == '\r' && p.peekAt(1) == '\n') {
			// empty line
			p.advance()
			breaks++
			continue
		}
		if detectIndent < 0 {
			detectIndent = ind
			if ind == 0 {
				return nil, p.errf("did not find expected non-space content")
			}
		}
		if ind < detectIndent {
			// end of block scalar
			p.pos = lineStart
			p.col = 0
			break
		}
		// consume detectIndent spaces
		p.pos = lineStart
		p.advanceN(detectIndent)
		// restore col
		p.col = detectIndent
		if !sawContent {
			for breaks > 0 {
				b.WriteByte('\n')
				breaks--
			}
		}
		sawContent = true
		for breaks > 0 {
			b.WriteByte('\n')
			breaks--
		}
		// copy the rest of the line
		for !p.atEnd() {
			c := p.peek()
			if c == '\n' {
				break
			}
			if c == '\r' && p.peekAt(1) == '\n' {
				break
			}
			b.WriteByte(c)
			p.advance()
		}
		b.WriteByte('\n')
		if !p.atEnd() && p.peek() == '\r' {
			p.advance()
		}
		if !p.atEnd() && p.peek() == '\n' {
			p.advance()
		}
	}
	v := b.String()
	// apply chomping
	switch chomp {
	case '-':
		v = strings.TrimRight(v, "\n")
	case '+':
		// keep
	default:
		if strings.HasSuffix(v, "\n") {
			v = strings.TrimSuffix(v, "\n")
		}
	}
	// folded style: fold line breaks
	if style == stFolded {
		v = foldBlockScalar(v)
	}
	n := &node{kind: nScalar, value: v, style: style, tag: "!!str"}
	if tag != "" {
		n.tag = tag
	}
	return n, nil
}

func foldBlockScalar(v string) string {
	lines := strings.Split(v, "\n")
	if len(lines) > 0 {
		lines = lines[:len(lines)-1]
	}
	var out strings.Builder
	for i, l := range lines {
		if i > 0 {
			if l == "" {
				out.WriteByte('\n')
			} else {
				out.WriteByte(' ')
			}
		}
		out.WriteString(l)
	}
	return out.String()
}

// parseBlockSequence parses a block sequence at the given indent.
func (p *parser) parseBlockSequence(indent int) (*node, error) {
	n := &node{kind: nSeq}
	for {
		if p.atEnd() {
			break
		}
		if p.col != indent {
			break
		}
		if p.peek() != '-' || !isBlankz(p.peekAt(1)) {
			break
		}
		if p.hasPrefix("---") {
			break
		}
		p.advance() // -
		p.skipSpacesOnLine()
		var item *node
		var err error
		if p.atEnd() || p.peek() == '\n' || p.peek() == '\r' {
			// item on the following lines
			p.skipToContent()
			if p.atEnd() || p.col <= indent {
				item = &node{kind: nScalar, value: "", style: stPlain, tag: "!!null"}
			} else {
				item, err = p.parseBlockNode(indent)
				if err != nil {
					return nil, err
				}
			}
		} else if p.peek() == '-' && isBlankz(p.peekAt(1)) {
			// nested sequence on the same line
			item, err = p.parseBlockSequence(p.col)
			if err != nil {
				return nil, err
			}
		} else if p.peek() == '{' || p.peek() == '[' {
			item, err = p.parseFlowNode()
			if err != nil {
				return nil, err
			}
		} else {
			// properties or scalar
			var anchor, tag string
			for {
				if p.peek() == '&' {
					p.advance()
					name, e := p.scanName()
					if e != nil {
						return nil, e
					}
					anchor = name
					p.skipSpacesOnLine()
					continue
				}
				if p.peek() == '!' {
					t, e := p.scanTag()
					if e != nil {
						return nil, e
					}
					tag = t
					p.skipSpacesOnLine()
					continue
				}
				break
			}
			if p.peek() == '*' {
				p.advance()
				name, e := p.scanName()
				if e != nil {
					return nil, e
				}
				item = &node{kind: nAlias, value: name}
			} else if p.peek() == '|' || p.peek() == '>' {
				item, err = p.parseBlockScalar(p.col, tag)
				if err != nil {
					return nil, err
				}
			} else {
				item, err = p.scanScalarNode(false)
				if err != nil {
					return nil, err
				}
				if tag != "" {
					item.tag = tag
				}
				// key in a mapping that starts on the same line as '-'
				p.skipSpacesOnLine()
				if p.peek() == ':' && isBlankz(p.peekAt(1)) {
					p.advance()
					m := &node{kind: nMap}
					key := item
					val, e := p.parseMappingValue(indent)
					if e != nil {
						return nil, e
					}
					m.pairs = append(m.pairs, [2]*node{key, val})
					// continue the mapping at indent+2
					if err := p.continueMapping(m, indent+2); err != nil {
						return nil, err
					}
					item = m
				}
			}
			if anchor != "" {
				p.anchors[anchor] = item
			}
		}
		n.items = append(n.items, item)
		p.skipToContent()
	}
	return n, nil
}

// continueMapping continues parsing a block mapping at the given indent.
func (p *parser) continueMapping(m *node, indent int) error {
	for {
		p.skipToContent()
		if p.atEnd() || p.col < indent {
			return nil
		}
		if p.hasPrefix("---") && isBlankz(p.peekAt(3)) || p.hasPrefix("...") && isBlankz(p.peekAt(3)) {
			return nil
		}
		if p.col != indent {
			return nil
		}
		if p.peek() == '-' && isBlankz(p.peekAt(1)) {
			return nil
		}
		var ka, kt string
		for {
			if p.peek() == '&' {
				p.advance()
				name, e := p.scanName()
				if e != nil {
					return e
				}
				ka = name
				p.skipSpacesOnLine()
				continue
			}
			if p.peek() == '!' {
				t, e := p.scanTag()
				if e != nil {
					return e
				}
				kt = t
				p.skipSpacesOnLine()
				continue
			}
			break
		}
		key, err := p.scanScalarNode(false)
		if err != nil {
			return err
		}
		p.skipSpacesOnLine()
		if p.peek() != ':' {
			return p.errf("could not find expected ':'")
		}
		p.advance()
		val, err := p.parseMappingValue(indent)
		if err != nil {
			return err
		}
		m.pairs = append(m.pairs, [2]*node{key, val})
	}
}

// nodeToValue converts a node tree to ordered values, resolving aliases and tags.
func nodeToValue(n *node, p *parser) (interface{}, error) {
	return nodeToValueRec(n, p, 0)
}

func nodeToValueRec(n *node, p *parser, depth int) (interface{}, error) {
	if depth > 200 {
		return nil, errors.New("yaml: exceeded max depth")
	}
	switch n.kind {
	case nAlias:
		target, ok := p.anchors[n.value]
		if !ok {
			return nil, fmt.Errorf("yaml: unknown anchor '%s' referenced", n.value)
		}
		return nodeToValueRec(target, p, depth+1)
	case nSeq:
		items := make([]interface{}, 0, len(n.items))
		for _, it := range n.items {
			v, err := nodeToValueRec(it, p, depth+1)
			if err != nil {
				return nil, err
			}
			items = append(items, v)
		}
		return items, nil
	case nMap:
		m := order.MapSlice{}
		for _, pr := range n.pairs {
			kv, err := nodeToValueRec(pr[0], p, depth+1)
			if err != nil {
				return nil, err
			}
			// merge key
			if isMergeKey(pr[0]) {
				switch mv := kv.(type) {
				case order.MapSlice:
					for _, it := range mv {
						m = append(m, it)
					}
					continue
				case []interface{}:
					bad := false
					var merged order.MapSlice
					for _, e := range mv {
						if ms, ok := e.(order.MapSlice); ok {
							for _, it := range ms {
								merged = append(merged, it)
							}
						} else {
							bad = true
						}
					}
					if bad {
						return nil, errors.New("yaml: map merge requires map or sequence of maps as the value")
					}
					for _, it := range merged {
						m = append(m, it)
					}
					continue
				default:
					return nil, errors.New("yaml: map merge requires map or sequence of maps as the value")
				}
			}
			vv, err := nodeToValueRec(pr[1], p, depth+1)
			if err != nil {
				return nil, err
			}
			m = append(m, order.MapItem{Key: kv, Val: vv})
		}
		return m, nil
	case nScalar:
		return decodeScalarNode(n)
	}
	return nil, nil
}

func isMergeKey(k *node) bool {
	if k.kind != nScalar {
		return false
	}
	if k.tag != "" {
		return shortTag(k.tag) == "!!merge"
	}
	return resolveTag(k.value) == "!!merge"
}

// decodeScalarNode converts a scalar node to a value.
func decodeScalarNode(n *node) (interface{}, error) {
	tag := n.tag
	if tag == "" {
		if n.style == stPlain {
			tag = resolveTag(n.value)
		} else {
			tag = "!!str"
		}
	}
	return decodeScalar(shortTag(tag), n.value)
}

