// Package dt holds the TOML date/time value kinds.
package dt

import "time"

// LocalDate is a TOML local date (no time, no zone).
type LocalDate struct {
	Year  int
	Month int
	Day   int
}

// LocalTime is a TOML local time (no date, no zone).
type LocalTime struct {
	Hour      int
	Minute    int
	Second    int
	Nanosecond int
}

// LocalDateTime is a TOML local date-time (no zone).
type LocalDateTime struct {
	Date LocalDate
	Time LocalTime
}

// Time converts to a UTC time.Time.
func (d LocalDate) Time() time.Time {
	return time.Date(d.Year, time.Month(d.Month), d.Day, 0, 0, 0, 0, time.UTC)
}

// Time converts to a UTC time.Time.
func (t LocalTime) Time() time.Time {
	return time.Date(0, time.January, 1, t.Hour, t.Minute, t.Second, t.Nanosecond, time.UTC)
}

// Time converts to a UTC time.Time.
func (d LocalDateTime) Time() time.Time {
	return time.Date(d.Date.Year, time.Month(d.Date.Month), d.Date.Day,
		d.Time.Hour, d.Time.Minute, d.Time.Second, d.Time.Nanosecond, time.UTC)
}

// String renders the local date.
func (d LocalDate) String() string {
	return fmtDate(d.Year, d.Month, d.Day)
}

// String renders the local time.
func (t LocalTime) String() string {
	return fmtTime(t.Hour, t.Minute, t.Second, t.Nanosecond)
}

// String renders the local date-time.
func (d LocalDateTime) String() string {
	return fmtDate(d.Date.Year, d.Date.Month, d.Date.Day) + "T" + fmtTime(d.Time.Hour, d.Time.Minute, d.Time.Second, d.Time.Nanosecond)
}

func fmtDate(y, m, d int) string {
	return pad4(y) + "-" + pad2(m) + "-" + pad2(d)
}

func fmtTime(h, mi, s, ns int) string {
	base := pad2(h) + ":" + pad2(mi) + ":" + pad2(s)
	if ns > 0 {
		base += nanoString(ns)
	}
	return base
}

func pad2(v int) string {
	s := itoa(v)
	if len(s) < 2 {
		s = "0" + s
	}
	return s
}

func pad4(v int) string {
	s := itoa(v)
	for len(s) < 4 {
		s = "0" + s
	}
	return s
}

func itoa(v int) string {
	if v == 0 {
		return "0"
	}
	neg := v < 0
	if neg {
		v = -v
	}
	var b [20]byte
	i := len(b)
	for v > 0 {
		i--
		b[i] = byte('0' + v%10)
		v /= 10
	}
	if neg {
		i--
		b[i] = '-'
	}
	return string(b[i:])
}

// nanoString formats a nanosecond fraction without a leading dot, trimming
// trailing zeros (like Go's RFC3339Nano).
func nanoString(ns int) string {
	// scale to 9 digits
	s := itoa(ns)
	for len(s) < 9 {
		s = "0" + s
	}
	for len(s) > 0 && s[len(s)-1] == '0' {
		s = s[:len(s)-1]
	}
	if s == "" {
		return ""
	}
	return "." + s
}
