	"+.Inf": {floatTag, math.Inf(1)},
	"+.INF": {floatTag, math.Inf(1)},
	"-.inf": {floatTag, math.Inf(-1)},
	"-.Inf": {floatTag, math.Inf(-1)},
	"-.INF": {floatTag, math.Inf(-1)},
