var resolveTable = buildResolveTable()

func buildResolveTable() [256]byte {
	var t [256]byte
	t['+'] = 'S'
	t['-'] = 'S'
	for _, c := range "0123456789" {
		t[c] = 'D'
	}
	for _, c := range "yYnNtTfFoO~" {
		t[c] = 'M'
	}
	t['.'] = '.'
	t['<'] = '<'
	return t
}

// resolveTag returns the tag a plain scalar would resolve to.
func resolveTag(in string) string {
	tag, _ := resolve("", in)
	return tag
}

// resolve resolves a scalar value, mirroring the YAML resolver.
func resolve(tag string, in string) (rtag string, out interface{}) {
	tag = shortTag(tag)
	if tag == strTag || tag == binaryTag {
		return tag, in
	}
	if in == "" && tag == "" {
		return nullTag, nil
	}
	hint := byte('N')
	if in != "" {
		hint = resolveTable[in[0]]
	}
	if hint != 0 && tag != strTag && tag != binaryTag {
		if item, ok := resolveMap[in]; ok {
			rtag = item.tag
			out = item.val
			return finishResolve(tag, in, rtag, out)
		}
		switch hint {
		case 'M':
			// already handled by the map
		case '.':
			f, err := strconv.ParseFloat(in, 64)
			if err == nil {
				return finishResolve(tag, in, floatTag, f)
			}
		case 'D', 'S':
			if tag == "" || tag == timestampTag {
				if t, ok := parseTimestamp(in); ok {
					return finishResolve(tag, in, timestampTag, t)
				}
			}
			plain := strings.Replace(in, "_", "", -1)
			if iv, err := strconv.ParseInt(plain, 0, 64); err == nil {
				return finishResolve(tag, in, intTag, iv)
			}
			if uv, err := strconv.ParseUint(plain, 0, 64); err == nil {
				return finishResolve(tag, in, intTag, uv)
			}
			if yamlStyleFloat.MatchString(plain) {
				if f, err := strconv.ParseFloat(plain, 64); err == nil {
					return finishResolve(tag, in, floatTag, f)
				}
			}
			if strings.HasPrefix(plain, "0b") {
				if iv, err := strconv.ParseInt(plain[2:], 2, 64); err == nil {
					return finishResolve(tag, in, intTag, iv)
				}
				if uv, err := strconv.ParseUint(plain[2:], 2, 64); err == nil {
					return finishResolve(tag, in, intTag, uv)
				}
			} else if strings.HasPrefix(plain, "-0b") {
				if iv, err := strconv.ParseInt("-"+plain[3:], 2, 64); err == nil {
					return finishResolve(tag, in, intTag, iv)
				}
			}
			if strings.HasPrefix(plain, "0o") {
				if iv, err := strconv.ParseInt(plain[2:], 8, 64); err == nil {
					return finishResolve(tag, in, intTag, iv)
				}
				if uv, err := strconv.ParseUint(plain[2:], 8, 64); err == nil {
					return finishResolve(tag, in, intTag, uv)
				}
			} else if strings.HasPrefix(plain, "-0o") {
				if iv, err := strconv.ParseInt("-"+plain[3:], 8, 64); err == nil {
					return finishResolve(tag, in, intTag, iv)
				}
			}
		}
	}
	return finishResolve(tag, in, strTag, in)
}

// finishResolve implements the tag-compatibility check of the YAML resolver.
func finishResolve(tag, in, rtag string, out interface{}) (string, interface{}) {
	if tag == "" || tag == rtag || tag == strTag || tag == binaryTag {
		return rtag, out
	}
	if tag == floatTag && rtag == intTag {
		switch v := out.(type) {
		case int64:
			return floatTag, float64(v)
		case int:
			return floatTag, float64(v)
		case uint64:
			return floatTag, float64(v)
		}
	}
	panic(scalarDecodeErr(rtag, in, tag))
}

func scalarDecodeErr(rtag, in, tag string) error {
	return fmt.Errorf("yaml: cannot decode %s `%s` as a %s", rtag, in, tag)
}

func decodeScalar(tag string, in string) (interface{}, error) {
	rtag, out, err := resolveSafe(tag, in)
	if err != nil {
		return nil, err
	}
	switch rtag {
	case nullTag:
		return nil, nil
	case boolTag:
		return out.(bool), nil
	case intTag:
		return out, nil
	case floatTag:
		return out, nil
	case strTag:
		return in, nil
	case binaryTag:
		return in, nil
	case timestampTag:
		return out, nil
	case mergeTag:
		return out, nil
	}
	return in, nil
}

// resolveSafe wraps resolve so that tag mismatches become "scalar decode error".
func resolveSafe(tag, in string) (string, interface{}, error) {
	defer func() {
		if r := recover(); r != nil {
			err, ok := r.(error)
			if ok {
				panic(fmt.Errorf("scalar decode error: %s", err.Error()))
			}
			panic(r)
		}
	}()
	rtag, out := resolve(tag, in)
	return rtag, out, nil
}

var allowedTimestampFormats = []string{
	"2006-1-2T15:4:5.999999999Z07:00",
	"2006-1-2t15:4:5.999999999Z07:00",
	"2006-1-2 15:4:5.999999999",
	"2006-1-2",
}

func parseTimestamp(s string) (time.Time, bool) {
	i := 0
	for ; i < len(s); i++ {
		if c := s[i]; c < '0' || c > '9' {
			break
		}
	}
	if i != 4 || i == len(s) || s[i] != '-' {
		return time.Time{}, false
	}
	for _, format := range allowedTimestampFormats {
		if t, err := time.Parse(format, s); err == nil {
			return t, true
		}
	}
	return time.Time{}, false
}

// utf8 helpers used by the writers
func utf8DecodeRuneInString(s string) (rune int, size int) {
	r, sz := utf8.DecodeRuneInString(s)
	return int(r), sz
}

// utf8EncodeRune encodes a code point into buf at i and returns the new index.
func utf8EncodeRune(buf []byte, i int, r int) int {
	n := utf8.EncodeRune(buf[i:], rune(r))
	return i + n
}

// width returns the byte length of the UTF-8 sequence starting at b.
func width(b byte) int {
	if b < 0x80 {
		return 1
	}
	if b < 0xE0 {
		return 2
	}
	if b < 0xF0 {
		return 3
	}
	if b < 0xF8 {
		return 4
	}
	return 1
}
