const version = "v0.0.0"

const helpText = `Usage: %s [-][ytjcrneikhv]

Convert between YAML, TOML, JSON, and HCL.
Preserves map order.

-x[x]  Convert using stdin. Valid options:
          -yj, -y = YAML to JSON (default)
          -yy     = YAML to YAML
          -yt     = YAML to TOML
          -yc     = YAML to HCL
          -tj, -t = TOML to JSON
          -ty     = TOML to YAML
          -tt     = TOML to TOML
          -tc     = TOML to HCL
          -jj     = JSON to JSON
          -jy, -r = JSON to YAML
          -jt     = JSON to TOML
          -jc     = JSON to HCL
          -cy     = HCL to YAML
          -ct     = HCL to TOML
          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version
`

type options struct {
	in    byte // 'y','t','j','c'
	out   byte
	noInf bool
	indent bool
	escape bool
	keys  bool
}

func printHelp(w io.Writer) {
	fmt.Fprintf(w, helpText, os.Args[0])
}

func fail(msg string) {
	printHelp(os.Stderr)
	fmt.Fprintf(os.Stderr, "Error: %s\n", msg)
	os.Exit(1)
}

func main() {
	opts, showHelp, showVersion, err := parseArgs(os.Args[1:])
	if err != nil {
		fail(err.Error())
		return
	}
	if showHelp {
		printHelp(os.Stdout)
		return
	}
	if err := validateFlags(opts); err != nil {
		fail(err.Error())
		return
	}
	if showVersion {
		fmt.Println(version)
		return
	}
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading stdin: %s\n", err)
		os.Exit(1)
	}
	v, err := convert(opts, data)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n", err)
		os.Exit(1)
	}
	os.Stdout.Write(v)
}

func parseArgs(args []string) (opts options, showHelp, showVersion bool, err error) {
	var invalid []string
	var formats []byte
	for _, arg := range args {
		s := strings.TrimLeft(arg, "-")
		for i := 0; i < len(s); i++ {
			c := s[i]
			switch c {
			case 'h':
				showHelp = true
			case 'v':
				showVersion = true
			case 'n':
				opts.noInf = true
			case 'i':
				opts.indent = true
			case 'e':
				opts.escape = true
			case 'k':
				opts.keys = true
			case 'y', 't', 'j', 'c':
				formats = append(formats, c)
			case '-':
				// ignored
			default:
				invalid = append(invalid, string(c))
			}
		}
	}
	if len(invalid) > 0 {
		return opts, false, false, fmt.Errorf("invalid flags specified: %s", strings.Join(invalid, " "))
	}
	switch len(formats) {
	case 0:
		opts.in = 'y'
		opts.out = 'j'
	case 1:
		opts.in = formats[0]
		opts.out = 'j'
	default:
		opts.in = formats[len(formats)-2]
		opts.out = formats[len(formats)-1]
	}
	return opts, showHelp, showVersion, nil
}

func validateFlags(o options) error {
	switch {
	case o.keys && o.out != 'y':
		return fmt.Errorf("flag -k only valid for YAML output")
	case o.escape && o.out != 'j':
		return fmt.Errorf("flag -e only valid for JSON output")
	case o.indent && o.out != 'j' && o.out != 't':
		return fmt.Errorf("flag -i only valid for JSON or TOML output")
	}
	return nil
}

func convert(o options, data []byte) ([]byte, error) {
	var v interface{}
	var err error
	switch o.in {
	case 'y':
		v, err = parseYAML(data)
		if err != nil {
			return nil, fmt.Errorf("Error parsing YAML: %s", err)
		}
	case 'j':
		v, err = parseJSONInput(data)
		if err != nil {
			return nil, fmt.Errorf("Error parsing JSON: %s", err)
		}
	case 't':
		v, err = parseTOML(data)
		if err != nil {
			return nil, fmt.Errorf("Error parsing TOML: %s", err)
		}
	case 'c':
		v, err = parseHCL(data)
		if err != nil {
			return nil, fmt.Errorf("Error parsing HCL: %s", err)
		}
	}
	if o.in == 'j' && !o.noInf {
		v = convertInfStringsIn(v)
	}
	if o.keys && o.out == 'y' {
		v = parseKeys(v)
	}
	switch o.out {
	case 'j':
		return encodeJSON(v, encOpts{indent: o.indent, escapeHTML: o.escape, noInf: o.noInf}), nil
	case 'y':
		b, err := encodeYAML(v, o.noInf)
		if err != nil {
			return nil, fmt.Errorf("Error writing YAML: %s", err)
		}
		return b, nil
	case 't':
		return encodeTOML(v, o), nil
	case 'c':
		b, err := encodeHCL(v, o.noInf)
		if err != nil {
			return nil, fmt.Errorf("Error writing HCL: %s", err)
		}
		return b, nil
	}
	return nil, fmt.Errorf("unknown output format")
}

// convertInfStringsIn converts the "Infinity"/"NaN" strings of a JSON input to floats.
func convertInfStringsIn(v interface{}) interface{} {
	switch t := v.(type) {
	case string:
		switch t {
		case "Infinity":
			return mathInf(1)
		case "-Infinity":
			return mathInf(-1)
		case "NaN":
			return mathNaN()
		}
		return t
	case order.MapSlice:
		for i := range t {
			t[i].Val = convertInfStringsIn(t[i].Val)
		}
		return t
	case []interface{}:
		for i := range t {
			t[i] = convertInfStringsIn(t[i])
		}
		return t
	}
	return v
}

// parseKeys attempts to parse string keys as JSON values (-k flag).
func parseKeys(v interface{}) interface{} {
	switch t := v.(type) {
	case order.MapSlice:
		out := make(order.MapSlice, 0, len(t))
		for _, it := range t {
			key := it.Key
			if s, ok := key.(string); ok {
				pv, err := parseJSONValue([]byte(s))
				if err == nil {
					key = pv
				}
			}
			out = append(out, order.MapItem{Key: key, Val: parseKeys(it.Val)})
		}
		return out
	case []interface{}:
		for i := range t {
			t[i] = parseKeys(t[i])
		}
		return t
	}
	return v
}
