package main

import (
	"fmt"
	"math"
	"strconv"
	"unicode/utf16"
	"unicode/utf8"
)

// strict JSON validation, mirroring encoding/json's error messages.

type jsonValidator struct {
	src []byte
	pos int
}

func (d *jsonValidator) err(context string, c byte) error {
	return fmt.Errorf("invalid character %s %s", quoteChar(c), context)
}

func quoteChar(c byte) string {
	if c == '\'' {
		return `'\''`
	}
	if c == '"' {
		return `'"'`
	}
	s := strconv.Quote(string(c))
	return "'" + s[1:len(s)-1] + "'"
}

func (d *jsonValidator) peek() byte {
	if d.pos >= len(d.src) {
		return 0
	}
	return d.src[d.pos]
}

func (d *jsonValidator) skipWS() {
	for d.pos < len(d.src) {
		switch d.src[d.pos] {
		case ' ', '\t', '\n', '\r':
			d.pos++
		default:
			return
		}
	}
}

// validateJSON mimics json.Unmarshal (with UseNumber) error reporting.
func validateJSON(src []byte) error {
	d := &jsonValidator{src: src}
	if err := d.parseValue(0); err != nil {
		return err
	}
	d.skipWS()
	if d.pos < len(d.src) {
		return d.err("after top-level value", d.src[d.pos])
	}
	return nil
}

func (d *jsonValidator) parseValue(depth int) error {
	if depth > 10000 {
		return fmt.Errorf("exceeded max depth")
	}
	d.skipWS()
	if d.pos >= len(d.src) {
		return fmt.Errorf("unexpected end of JSON input")
	}
	c := d.src[d.pos]
	switch {
	case c == '{':
		return d.parseObject(depth)
	case c == '[':
		return d.parseArray(depth)
	case c == '"':
		_, err := d.parseString()
		return err
	case c == '-' || (c >= '0' && c <= '9'):
		return d.parseNumber()
	default:
		return d.parseLiteral()
	}
}

func (d *jsonValidator) parseLiteral() error {
	start := d.pos
	c := d.src[d.pos]
	var want string
	var expect string
	switch {
	case c == 't':
		want, expect = "true", "rue"
		d.pos++
	case c == 'f':
		want, expect = "false", "alse"
		d.pos++
	case c == 'n':
		want, expect = "null", "ull"
		d.pos++
	default:
		return d.err("looking for beginning of value", c)
	}
	for i := 0; i < len(expect); i++ {
		if d.pos >= len(d.src) {
			return d.err("in literal "+want+" (expecting '"+string(expect[i])+"')", 0)
		}
		if d.src[d.pos] != expect[i] {
			return d.err("in literal "+want+" (expecting '"+string(expect[i])+"')", d.src[d.pos])
		}
		d.pos++
	}
	return nil
}

func (d *jsonValidator) parseNumber() error {
	start := d.pos
	if d.pos < len(d.src) && d.src[d.pos] == '-' {
		d.pos++
	}
	if d.pos >= len(d.src) {
		return d.err("in numeric literal", 0)
	}
	c := d.src[d.pos]
	if c == '0' {
		d.pos++
	} else if c >= '1' && c <= '9' {
		d.pos++
		for d.pos < len(d.src) && d.src[d.pos] >= '0' && d.src[d.pos] <= '9' {
			d.pos++
		}
	} else {
		return d.err("in numeric literal", c)
	}
	if d.pos < len(d.src) && d.src[d.pos] == '.' {
		d.pos++
		if d.pos >= len(d.src) || d.src[d.pos] < '0' || d.src[d.pos] > '9' {
			var bad byte = 0
			if d.pos < len(d.src) {
				bad = d.src[d.pos]
			}
			return d.err("after decimal point in numeric literal", bad)
		}
		for d.pos < len(d.src) && d.src[d.pos] >= '0' && d.src[d.pos] <= '9' {
			d.pos++
		}
	}
	if d.pos < len(d.src) && (d.src[d.pos] == 'e' || d.src[d.pos] == 'E') {
		d.pos++
		if d.pos < len(d.src) && (d.src[d.pos] == '+' || d.src[d.pos] == '-') {
			d.pos++
		}
		if d.pos >= len(d.src) || d.src[d.pos] < '0' || d.src[d.pos] > '9' {
			var bad byte = 0
			if d.pos < len(d.src) {
				bad = d.src[d.pos]
			}
			return d.err("in exponent of numeric literal", bad)
		}
		for d.pos < len(d.src) && d.src[d.pos] >= '0' && d.src[d.pos] <= '9' {
			d.pos++
		}
	}
	_ = start
	return nil
}

func (d *jsonValidator) parseString() (string, error) {
	d.pos++ // opening quote
	var out []byte
	for {
		if d.pos >= len(d.src) {
			return "", fmt.Errorf("unexpected end of JSON input")
		}
		c := d.src[d.pos]
		if c == '"' {
			d.pos++
			return string(out), nil
		}
		if c == '\\' {
			d.pos++
			if d.pos >= len(d.src) {
				return "", fmt.Errorf("unexpected end of JSON input")
			}
			e := d.src[d.pos]
			switch e {
			case '"', '\\', '/':
				out = append(out, e)
				d.pos++
			case 'b':
				out = append(out, '\b')
				d.pos++
			case 'f':
				out = append(out, '\f')
				d.pos++
			case 'n':
				out = append(out, '\n')
				d.pos++
			case 'r':
				out = append(out, '\r')
				d.pos++
			case 't':
				out = append(out, '\t')
				d.pos++
			case 'u':
				d.pos++
				r, err := d.parseHex4()
				if err != nil {
					return "", err
				}
				if utf16.IsSurrogate(rune16(r)) {
					if d.pos+1 < len(d.src) && d.src[d.pos] == '\\' && d.src[d.pos+1] == 'u' {
						save := d.pos
						d.pos += 2
						r2, err := d.parseHex4()
						if err != nil {
							return "", err
						}
						if dec := utf16.DecodeRune(rune16(r), rune16(r2)); dec != 0xfffd {
							out = append(out, utf8RuneBytes(dec)...)
							continue
						}
						d.pos = save
					}
					out = append(out, utf8RuneBytes(0xfffd)...)
				} else {
					out = append(out, utf8RuneBytes(int(r))...)
				}
			default:
				return "", d.err("in string escape code", e)
			}
			continue
		}
		if c < 0x20 {
			return "", d.err("in string literal", c)
		}
		out = append(out, c)
		d.pos++
	}
}

func (d *jsonValidator) parseHex4() (uint16, error) {
	if d.pos+4 > len(d.src) {
		return 0, d.err("in \\u hexadecimal character escape", 0)
	}
	var v uint16
	for i := 0; i < 4; i++ {
		c := d.src[d.pos+i]
		var n uint16
		switch {
		case c >= '0' && c <= '9':
			n = uint16(c - '0')
		case c >= 'a' && c <= 'f':
			n = uint16(c-'a') + 10
		case c >= 'A' && c <= 'F':
			n = uint16(c-'A') + 10
		default:
			return 0, d.err("in \\u hexadecimal character escape", c)
		}
		v = v*16 + n
	}
	d.pos += 4
	return v, nil
}

func (d *jsonValidator) parseObject(depth int) error {
	d.pos++ // {
	d.skipWS()
	if d.pos < len(d.src) && d.src[d.pos] == '}' {
		d.pos++
		return nil
	}
	for {
		d.skipWS()
		if d.pos >= len(d.src) {
			return fmt.Errorf("unexpected end of JSON input")
		}
		if d.src[d.pos] != '"' {
			return d.err("looking for beginning of object key string", d.src[d.pos])
		}
		if _, err := d.parseString(); err != nil {
			return err
		}
		d.skipWS()
		if d.pos >= len(d.src) {
			return fmt.Errorf("unexpected end of JSON input")
		}
		if d.src[d.pos] != ':' {
			return d.err("after object key", d.src[d.pos])
		}
		d.pos++
		if err := d.parseValue(depth + 1); err != nil {
			return err
		}
		d.skipWS()
		if d.pos >= len(d.src) {
			return fmt.Errorf("unexpected end of JSON input")
		}
		switch d.src[d.pos] {
		case ',':
			d.pos++
			continue
		case '}':
			d.pos++
			return nil
		default:
			return d.err("after object key:value pair", d.src[d.pos])
		}
	}
}

func (d *jsonValidator) parseArray(depth int) error {
	d.pos++ // [
	d.skipWS()
	if d.pos < len(d.src) && d.src[d.pos] == ']' {
		d.pos++
		return nil
	}
	for {
		if err := d.parseValue(depth + 1); err != nil {
			return err
		}
		d.skipWS()
		if d.pos >= len(d.src) {
			return fmt.Errorf("unexpected end of JSON input")
		}
		switch d.src[d.pos] {
		case ',':
			d.pos++
			continue
		case ']':
			d.pos++
			return nil
		default:
			return d.err("after array element", d.src[d.pos])
		}
	}
}

func rune16(r uint16) rune { return rune(r) }

func utf8RuneBytes(r int) []byte {
	var b [4]byte
	n := utf8.EncodeRune(b[:], rune(r))
	return b[:n]
}

// parseJSONInput validates the JSON and then parses it with the YAML parser so
// that key order and duplicates are preserved.
func parseJSONInput(data []byte) (interface{}, error) {
	if err := validateJSON(data); err != nil {
		return nil, err
	}
	return parseYAML(data)
}

// parseJSONValue parses a single JSON value (used by the -k flag).
func parseJSONValue(data []byte) (interface{}, error) {
	if err := validateJSON(data); err != nil {
		return nil, err
	}
	return parseYAML(data)
}

func mathInf(sign int) float64 { return math.Inf(sign) }

func mathNaN() float64 { return math.NaN() }
EOF
echo ok"}

