	case int64:
		e.emitScalar(strconv.FormatInt(t, 10), true, stPlain, true)
	case uint64:
		e.emitScalar(strconv.FormatUint(t, 10), true, stPlain, true)
	case float64:
		e.emitScalar(formatYAMLFloat(t), true, stPlain, true)
	case time.Time:
		e.emitScalar(t.Format(time.RFC3339Nano), true, stPlain, true)
	case dt.LocalDate:
		e.emitScalar(t.String(), true, stPlain, true)
	case dt.LocalTime:
		e.emitScalar(t.String(), true, stPlain, true)
	case dt.LocalDateTime:
		e.emitScalar(t.String(), true, stPlain, true)
	case order.MapSlice:
		// complex key
		e.writeIndicator("?", true, false, false)
		e.emitMapping(t, len(t) == 0)
		e.writeIndicator(":", false, false, false)
		_ = t
	case []interface{}:
		e.writeIndicator("?", true, false, false)
		e.emitSequence(t, len(t) == 0)
	}
}

func (e *emitter) emitValue(v interface{}) {
	switch t := v.(type) {
	case order.MapSlice:
		e.emitMapping(t, len(t) == 0)
	case []interface{}:
		e.emitSequence(t, len(t) == 0)
	default:
		e.emitNode(v, false, false, true)
	}
}

func (e *emitter) emitSequence(s []interface{}, empty bool) {
	if empty {
		e.writeIndicator("[]", true, false, false)
		return
	}
	e.increaseIndent(false, false)
	for _, item := range s {
		e.writeIndicator("-", true, false, true)
		switch t := item.(type) {
		case order.MapSlice:
			e.emitMapping(t, len(t) == 0)
		case []interface{}:
			e.emitSequence(t, len(t) == 0)
