package main

import (
	"fmt"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"./order"
	"./dt"
)

const bestIndent = 2

type emitter struct {
	buf          []byte
	indent       int
	indents      []int
	column       int
	whitespace   bool
	indention    bool
	openEnded    bool
	mappingDepth int
	line         int
	err          error
}

func newEmitter() *emitter {
	return &emitter{indent: -1, whitespace: true, indention: true}
}

func (e *emitter) put(b byte) {
	e.buf = append(e.buf, b)
	e.column++
}

func (e *emitter) putBreak() {
	e.buf = append(e.buf, '\n')
	e.column = 0
	e.line++
	e.indention = true
}

func (e *emitter) writeIndent() {
	indent := e.indent
	if indent < 0 {
		indent = 0
	}
	if !e.indention || e.column > indent {
		e.putBreak()
	}
	for e.column < indent {
		e.put(' ')
	}
	e.whitespace = true
	e.indention = true
}

func (e *emitter) writeIndicator(s string, needWhitespace, isWhitespace, isIndention bool) {
	if needWhitespace && !e.whitespace {
		e.put(' ')
	}
	for i := 0; i < len(s); i++ {
		e.put(s[i])
	}
	e.whitespace = isWhitespace
	e.indention = e.indention && isIndention
	e.openEnded = false
}

func (e *emitter) increaseIndent(flow, indentless bool) {
	e.indents = append(e.indents, e.indent)
	if e.indent < 0 {
		if flow {
			e.indent = bestIndent
		} else {
			e.indent = 0
		}
	} else if !indentless {
		e.indent += bestIndent
	}
}

func (e *emitter) restoreIndent() {
	e.indent = e.indents[len(e.indents)-1]
	e.indents = e.indents[:len(e.indents)-1]
}

// encodeYAML converts v to YAML text and validates it parses.
func encodeYAML(v interface{}, noInf bool) ([]byte, error) {
	e := newEmitter()
	e.emitDocument(v, noInf)
	text := string(e.buf)
	if _, err := parseYAMLText([]byte(text)); err != nil {
		return nil, err
	}
	return e.buf, nil
}

func (e *emitter) emitDocument(v interface{}, noInf bool) {
	e.emitNode(v, true, false, false)
}

// emitNode emits a value. root: top-level; sequence/mapping: inside those.
func (e *emitter) emitNode(v interface{}, root, sequence, mapping bool) {
	switch t := v.(type) {
	case nil:
		e.emitScalar("null", false, stPlain, true)
	case bool:
		if t {
			e.emitScalar("true", false, stPlain, true)
		} else {
			e.emitScalar("false", false, stPlain, true)
		}
	case string:
		e.emitString(t, false)
	case int64:
		e.emitScalar(strconv.FormatInt(t, 10), false, stPlain, true)
	case uint64:
		e.emitScalar(strconv.FormatUint(t, 10), false, stPlain, true)
	case float64:
		s := formatYAMLFloat(t)
		e.emitScalar(s, false, stPlain, true)
	case time.Time:
		e.emitScalar(t.Format(time.RFC3339Nano), false, stPlain, true)
	case dt.LocalDate:
		e.emitScalar(t.String(), false, stPlain, true)
	case dt.LocalTime:
		e.emitScalar(t.String(), false, stPlain, true)
	case dt.LocalDateTime:
		e.emitScalar(t.String(), false, stPlain, true)
	case order.MapSlice:
		e.emitMapping(t, len(t) == 0)
	case []interface{}:
		e.emitSequence(t, len(t) == 0)
	}
}

func formatYAMLFloat(f float64) string {
	s := strconv.FormatFloat(f, 'g', -1, 64)
	switch s {
	case "+Inf":
		return ".inf"
	case "-Inf":
		return "-.inf"
	case "NaN":
		return ".nan"
	}
	if !strings.ContainsAny(s, ".eE") {
		s += ".0"
	}
	return s
}

func (e *emitter) emitMapping(m order.MapSlice, empty bool) {
	if empty {
		e.writeIndicator("{}", true, false, false)
		return
	}
	e.increaseIndent(false, false)
	e.mappingDepth++
	for i, it := range m {
		_ = i
		e.writeIndent()
		// key
		e.emitKey(it.Key)
		e.writeIndicator(":", false, false, false)
		e.emitValue(it.Val)
	}
	e.mappingDepth--
	e.restoreIndent()
}

func (e *emitter) emitKey(k interface{}) {
	switch t := k.(type) {
	case string:
		e.emitString(t, true)
	case nil:
		e.emitScalar("null", true, stPlain, true)
	case bool:
		if t {
			e.emitScalar("true", true, stPlain, true)
		} else {
			e.emitScalar("false", true, stPlain, true)
		}
	case int64:
		e.emitScalar(strconv.FormatInt(t, 10), true, stPlain, true)
	case uint64:
		e.emitScalar(strconv.FormatUint(t, 10), true, stPlain, true)
	case float64:
		e.emitScalar(formatYAMLFloat(t), true, stPlain, true)
	case time.Time:
		e.emitScalar(t.Format(time.RFC3339Nano), true, stPlain, true)
	case dt.LocalDate:
		e.emitScalar(t.String(), true, stPlain, true)
	case dt.LocalTime:
		e.emitScalar(t.String(), true, stPlain, true)
	case dt.LocalDateTime:
		e.emitScalar(t.String(), true, stPlain, true)
	case order.MapSlice:
		// complex key
		e.writeIndicator("?", true, false, false)
		e.emitMapping(t, len(t) == 0)
		e.writeIndicator(":", false, false, false)
		_ = t
	case []interface{}:
		e.writeIndicator("?", true, false, false)
		e.emitSequence(t, len(t) == 0)
	}
}

func (e *emitter) emitValue(v interface{}) {
	switch t := v.(type) {
	case order.MapSlice:
		e.emitMapping(t, len(t) == 0)
	case []interface{}:
		e.emitSequence(t, len(t) == 0)
	default:
		e.emitNode(v, false, false, true)
	}
}

func (e *emitter) emitSequence(s []interface{}, empty bool) {
	if empty {
		e.writeIndicator("[]", true, false, false)
		return
	}
	e.increaseIndent(false, false)
	for _, item := range s {
		e.writeIndicator("-", true, false, true)
		switch t := item.(type) {
		case order.MapSlice:
			e.emitMapping(t, len(t) == 0)
		case []interface{}:
			e.emitSequence(t, len(t) == 0)
		default:
			e.emitScalarValue(item)
		}
	}
	e.restoreIndent()
}

func (e *emitter) emitScalarValue(v interface{}) {
	switch t := v.(type) {
	case nil:
		e.emitScalar("null", false, stPlain, true)
	case bool:
		if t {
			e.emitScalar("true", false, stPlain, true)
		} else {
			e.emitScalar("false", false, stPlain, true)
		}
	case string:
		e.emitString(t, false)
	case int64:
		e.emitScalar(strconv.FormatInt(t, 10), false, stPlain, true)
	case uint64:
		e.emitScalar(strconv.FormatUint(t, 10), false, stPlain, true)
	case float64:
		e.emitScalar(formatYAMLFloat(t), false, stPlain, true)
	case time.Time:
		e.emitScalar(t.Format(time.RFC3339Nano), false, stPlain, true)
	case dt.LocalDate:
		e.emitScalar(t.String(), false, stPlain, true)
	case dt.LocalTime:
		e.emitScalar(t.String(), false, stPlain, true)
	case dt.LocalDateTime:
		e.emitScalar(t.String(), false, stPlain, true)
	}
}

// emitString emits a string scalar, choosing the style like the YAML encoder.
func (e *emitter) emitString(s string, simpleKey bool) {
	canUsePlain := true
	if rtag, _ := resolve("", s); rtag != strTag {
		canUsePlain = false
	}
	if isBase60Float(s) || isOldBool(s) {
		canUsePlain = false
	}
	// merge key tag
	if s == "<<" {
		e.writeIndicator("!!merge", false, false, false)
		e.emitScalar(s, simpleKey, stPlain, true)
		return
	}
	var style int
	switch {
	case strings.Contains(s, "\n"):
		style = stLiteral
	case canUsePlain:
		style = stPlain
	default:
		style = stDouble
	}
	e.emitScalar(s, simpleKey, style, true)
}

func isOldBool(s string) bool {
	switch s {
	case "y", "Y", "yes", "Yes", "YES", "on", "On", "ON",
		"n", "N", "no", "No", "NO", "off", "Off", "OFF":
		return true
	}
	return false
}

var base60Re = regexpMustCompile(`^[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+(?:\.[0-9_]*)?$`)

func isBase60Float(s string) bool {
	if len(s) == 0 || (s[0] != '+' && s[0] != '-' && (s[0] < '0' || s[0] > '9')) {
		return false
	}
	return base60Re.MatchString(s)
}

// scalarData holds the analysis result of a scalar.
type scalarData struct {
	value              string
	multiline          bool
	flowPlainAllowed   bool
	blockPlainAllowed  bool
	singleQuotedAllowed bool
	blockAllowed       bool
}

func isSpaceB(b byte) bool { return b == ' ' }

func isBreakB(b byte) bool { return b == '\n' || b == '\r' }

func analyzeScalar(value string) scalarData {
	var d scalarData
	d.value = value
	if len(value) == 0 {
		d.multiline = false
		d.flowPlainAllowed = false
		d.blockPlainAllowed = true
		d.singleQuotedAllowed = true
		d.blockAllowed = false
		return d
	}
	var blockIndicators, flowIndicators, lineBreaks, specialCharacters, tabCharacters bool
	var leadingSpace, leadingBreak, trailingSpace, trailingBreak, breakSpace, spaceBreak bool
	precededByWhitespace := true
	previousSpace := false
	previousBreak := false
	if len(value) >= 3 && ((value[0] == '-' && value[1] == '-' && value[2] == '-') || (value[0] == '.' && value[1] == '.' && value[2] == '.')) {
		blockIndicators = true
		flowIndicators = true
	}
	for i, w := 0, 0; i < len(value); i += w {
		w = width(value[i])
		followedByWhitespace := i+w >= len(value) || isBlank(value, i+w)
		if i == 0 {
			switch value[i] {
			case '#', ',', '[', ']', '{', '}', '&', '*', '!', '|', '>', '\'', '"', '%', '@', '`':
				flowIndicators = true
				blockIndicators = true
			case '?', ':':
				flowIndicators = true
			case '-':
				if followedByWhitespace {
					flowIndicators = true
					blockIndicators = true
				}
			}
		} else {
			switch value[i] {
			case ',', '?', '[', ']', '{', '}':
				flowIndicators = true
			case ':':
				flowIndicators = true
				if followedByWhitespace {
					blockIndicators = true
				}
			case '#':
				if precededByWhitespace {
					flowIndicators = true
					blockIndicators = true
				}
			}
		}
		if value[i] == '\t' {
			tabCharacters = true
		} else if !isPrintable(value, i) {
			specialCharacters = true
		}
		if isSpace(value, i) {
			if i == 0 {
				leadingSpace = true
			}
			if i+w == len(value) {
				trailingSpace = true
			}
			if previousBreak {
				breakSpace = true
			}
			previousSpace = true
			previousBreak = false
		} else if isBreak(value, i) {
			lineBreaks = true
			if i == 0 {
				leadingBreak = true
			}
			if i+w == len(value) {
				trailingBreak = true
			}
			if previousSpace {
				spaceBreak = true
			}
			previousSpace = false
			previousBreak = true
		} else {
			previousSpace = false
			previousBreak = false
		}
		precededByWhitespace = isBlankzAt(value, i)
	}
	d.multiline = lineBreaks
	d.flowPlainAllowed = true
	d.blockPlainAllowed = true
	d.singleQuotedAllowed = true
	d.blockAllowed = true
	if leadingSpace || leadingBreak || trailingSpace || trailingBreak {
		d.flowPlainAllowed = false
		d.blockPlainAllowed = false
	}
	if trailingSpace {
		d.blockAllowed = false
	}
	if breakSpace {
		d.flowPlainAllowed = false
		d.blockPlainAllowed = false
		d.singleQuotedAllowed = false
	}
	if spaceBreak || tabCharacters || specialCharacters {
		d.flowPlainAllowed = false
		d.blockPlainAllowed = false
		d.singleQuotedAllowed = false
	}
	if spaceBreak || specialCharacters {
		d.blockAllowed = false
	}
	if lineBreaks {
		d.flowPlainAllowed = false
		d.blockPlainAllowed = false
	}
	if flowIndicators {
		d.flowPlainAllowed = false
	}
	if blockIndicators {
		d.blockPlainAllowed = false
	}
	return d
}

func isBlank(s string, i int) bool {
	if i >= len(s) {
		return true
	}
	return s[i] == ' ' || s[i] == '\t'
}

func isBlankzAt(s string, i int) bool {
	if i >= len(s) {
		return true
	}
	c := s[i]
	return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == 0
}

func isSpace(s string, i int) bool {
	if i >= len(s) {
		return false
	}
	return s[i] == ' '
}

func isBreak(s string, i int) bool {
	if i >= len(s) {
		return false
	}
	switch s[i] {
	case '\n', '\r':
		return true
	}
	return false
}

func isPrintable(s string, i int) bool {
	if i >= len(s) {
		return false
	}
	c := s[i]
	if c == 0x0A || c == 0x0D || c == 0x09 {
		return true
	}
	if c >= 0x20 && c <= 0x7E {
		return true
	}
	if c == 0xC2 {
		if i+1 < len(s) {
			r := s[i+1]
			if r >= 0xA0 && r <= 0xBF {
				return true
			}
		}
	}
	if c == 0xE2 {
		if i+2 < len(s) {
			r1 := s[i+1]
			r2 := s[i+2]
			if r1 == 0x80 && (r2 == 0x85 || r2 == 0xA8 || r2 == 0xA9) {
				return true
			}
		}
	}
	if c > 0x9F && c != 0xC2 && (c < 0xE2 || c > 0xE2) {
		// most multi-byte sequences are printable
		if c >= 0xE3 && c <= 0xF4 {
			return true
		}
	}
	return false
}

// chooseStyle picks the final scalar style.
func (e *emitter) chooseStyle(s string, requested int, simpleKey bool, flowLevel int) int {
	style := requested
	if simpleKey && analyzeScalar(s).multiline {
		style = stDouble
	}
	if style == stPlain {
		d := analyzeScalar(s)
		if flowLevel > 0 && !d.flowPlainAllowed || flowLevel == 0 && !d.blockPlainAllowed {
			style = stSingle
		}
		if len(s) == 0 && (flowLevel > 0 || simpleKey) {
			style = stSingle
		}
		if style == stSingle && d.multiline {
			style = stDouble
		}
	}
	if style == stLiteral || style == stFolded {
		d := analyzeScalar(s)
		if !d.blockAllowed || flowLevel > 0 || simpleKey {
			style = stDouble
		}
	}
	return style
}

// emitScalar writes a scalar with the chosen style.
func (e *emitter) emitScalar(value string, simpleKey bool, requested int, allowBreaks bool) {
	d := analyzeScalar(value)
	style := e.chooseStyle(value, requested, simpleKey, 0)
	switch style {
	case stPlain:
		e.writePlainScalar(value, allowBreaks)
	case stSingle:
		e.writeSingleQuoted(value, allowBreaks)
	case stDouble:
		e.writeDoubleQuoted(value)
	case stLiteral:
		e.writeLiteralScalar(value)
	case stFolded:
		e.writeLiteralScalar(value)
	}
	_ = d
}

func (e *emitter) writePlainScalar(value string, allowBreaks bool) {
	if !e.whitespace {
		e.put(' ')
	}
	spaces := false
	breaks := false
	for i := 0; i < len(value); {
		if isSpace(value, i) {
			if allowBreaks && !isSpace(value, i+1) && e.column > 80 && !spaces {
				e.writeIndent()
				i += width(value[i])
			} else {
				e.put(' ')
				i++
			}
			spaces = true
		} else if isBreak(value, i) {
			if !breaks && value[i] == '\n' {
				e.putBreak()
			}
			if !breaks {
				e.putBreak()
			}
			e.indention = true
			breaks = true
			i++
		} else {
			if breaks {
				e.writeIndent()
			}
			w := width(value[i])
			for j := 0; j < w && i < len(value); j++ {
				e.put(value[i])
				i++
			}
			e.indention = false
			spaces = false
			breaks = false
		}
	}
	e.whitespace = false
}

func (e *emitter) writeSingleQuoted(value string, allowBreaks bool) {
	e.writeIndicator("'", true, false, false)
	spaces := false
	breaks := false
	for i := 0; i < len(value); {
		if isSpace(value, i) {
			if allowBreaks && !isSpace(value, i+1) && e.column > 80 && !spaces && i > 0 && i < len(value)-1 {
				e.writeIndent()
				i++
			} else {
				e.put(' ')
				i++
			}
			spaces = true
		} else if isBreak(value, i) {
			if !breaks && value[i] == '\n' {
				e.putBreak()
			}
			if !breaks {
				e.putBreak()
			}
			e.indention = true
			breaks = true
			i++
		} else {
			if breaks {
				e.writeIndent()
			}
			if value[i] == '\'' {
				e.put('\'')
				e.put('\'')
				i++
			} else {
				w := width(value[i])
				for j := 0; j < w && i < len(value); j++ {
					e.put(value[i])
					i++
				}
			}
			e.indention = false
			spaces = false
			breaks = false
		}
	}
	e.writeIndicator("'", false, false, false)
	e.whitespace = false
}

func (e *emitter) writeDoubleQuoted(value string) {
	e.writeIndicator(`"`, true, false, false)
	for i := 0; i < len(value); {
		if !isPrintable(value, i) || value[i] == '"' || value[i] == '\\' || isBreak(value, i) || value[i] == '\t' {
			octet := value[i]
			var w int
			r := rune(octet)
			switch {
			case octet == '"':
				e.put('\\')
				e.put('"')
				i++
				continue
			case octet == '\\':
				e.put('\\')
				e.put('\\')
				i++
				continue
			case octet == 0x00:
				e.writeString(`\0`)
				i++
				continue
			case octet == 0x07:
				e.writeString(`\a`)
				i++
				continue
			case octet == 0x08:
				e.writeString(`\b`)
				i++
				continue
			case octet == 0x09:
				e.writeString(`\t`)
				i++
				continue
			case octet == 0x0A:
				e.writeString(`\n`)
				i++
				continue
			case octet == 0x0B:
				e.writeString(`\v`)
				i++
				continue
			case octet == 0x0C:
				e.writeString(`\f`)
				i++
				continue
			case octet == 0x0D:
				e.writeString(`\r`)
				i++
				continue
			case octet == 0x1B:
				e.writeString(`\e`)
				i++
				continue
			case octet == 0x22:
				e.writeString(`\"`)
				i++
				continue
			case octet == 0x5C:
				e.writeString(`\\`)
				i++
				continue
			case octet == 0x85:
				e.writeString(`\N`)
				i += 2
				continue
			case octet == 0xA0:
				e.writeString(`\_`)
				i += 2
				continue
			case octet == 0x2028:
				e.writeString(`\L`)
				i += 3
				continue
			case octet == 0x2029:
				e.writeString(`\P`)
				i += 3
				continue
			}
			if octet < 0x20 || octet == 0x7F {
				e.writeString(`\x`)
				e.put(hexUpper[octet>>4])
				e.put(hexUpper[octet&0xf])
				i++
				continue
			}
			// multi-byte
			if w, _ := utf8.DecodeRuneInString(value[i:]); w == 0xfffd && width(octet) == 1 {
				e.writeString(`\x`)
				e.put(hexUpper[octet>>4])
				e.put(hexUpper[octet&0xf])
				i++
				continue
			}
			_ = r
			w = width(octet)
			for j := 0; j < w && i < len(value); j++ {
				e.put(value[i])
				i++
			}
			continue
		}
		w := width(value[i])
		for j := 0; j < w && i < len(value); j++ {
			e.put(value[i])
			i++
		}
	}
	e.writeIndicator(`"`, false, false, false)
	e.whitespace = false
}

var hexUpper = "0123456789ABCDEF"

func (e *emitter) writeString(s string) {
	for i := 0; i < len(s); i++ {
		e.put(s[i])
	}
}

// writeBlockScalarHints writes the indentation indicator and chomping hint.
func (e *emitter) writeBlockScalarHints(value string) {
	if isSpace(value, 0) || isBreak(value, 0) {
		e.writeIndicator(strconv.Itoa(bestIndent), false, false, false)
	}
	e.openEnded = false
	var chomp string
	if len(value) == 0 {
		chomp = "-"
	} else {
		i := len(value) - 1
		for value[i]&0xC0 == 0x80 {
			i--
		}
		if !isBreak(value, i) {
			chomp = "-"
		} else if i == 0 {
			chomp = "+"
			e.openEnded = true
		} else {
			i--
			for i > 0 && value[i]&0xC0 == 0x80 {
				i--
			}
			if isBreak(value, i) {
				chomp = "+"
				e.openEnded = true
			}
		}
	}
	if chomp != "" {
		e.writeIndicator(chomp, false, false, false)
	}
}

// writeLiteralScalar writes a literal block scalar, applying yj's trimming quirk.
func (e *emitter) writeLiteralScalar(value string) {
	// yj trims leading newlines based on the mapping depth
	t := e.mappingDepth + 1
	k := 0
	for k < len(value) && value[k] == '\n' {
		k++
	}
	content := value
	if k > 0 {
		n := k
		if n > t {
			n = t
		}
		content = value[n:]
	}
	// hint value starts at value[t-1]
	hintOK := t-1 < len(value) && (isSpaceB(value[t-1]) || isBreakB(value[t-1]))
	// detect whether this is a sequence item context error case
	if e.seqItemProblem {
		e.emitSeqIndicatorError(value, t)
		return
	}
	if len(content) == 0 && !hintOK {
		e.emitScalar("", false, stDouble, true)
		return
	}
	e.writeIndicator("|", true, false, false)
	if hintOK {
		e.writeIndicator(strconv.Itoa(bestIndent), false, false, false)
	}
	e.writeBlockScalarHintsChomp(value)
	e.putBreak()
	e.indention = true
	e.whitespace = true
	breaks := true
	for i := 0; i < len(content); {
		if isBreak(content, i) {
			e.putBreak()
			i++
			e.indention = true
			breaks = true
		} else {
			if breaks {
				e.writeIndent()
			}
			w := width(content[i])
			for j := 0; j < w && i < len(content); j++ {
				e.put(content[i])
				i++
			}
			e.indention = false
			breaks = false
		}
	}
}

func (e *emitter) writeBlockScalarHintsChomp(value string) {
	// chomping computed from the original value
	var chomp string
	if len(value) == 0 {
		chomp = "-"
	} else {
		i := len(value) - 1
		for i > 0 && value[i]&0xC0 == 0x80 {
			i--
		}
		if !isBreak(value, i) {
			chomp = "-"
		} else if i == 0 {
			chomp = "+"
			e.openEnded = true
		} else {
			i--
			for i > 0 && value[i]&0xC0 == 0x80 {
				i--
			}
			if isBreak(value, i) {
				chomp = "+"
				e.openEnded = true
			}
		}
	}
	if chomp != "" {
		e.writeIndicator(chomp, false, false, false)
	}
}

// seqItemProblem tracks that the current scalar is a sequence item while inside
// at least one mapping, which makes yj's emitted YAML invalid.
var seqItemErrorItemIndex int
var seqItemErrorDepth int

func (e *emitter) emitSeqIndicatorError(value string, t int) {
	e.err = fmt.Errorf("yaml: line %d: did not find expected '-' indicator", seqItemErrorItemIndex)
}

