package main

import (
	"regexp"
	"strconv"
	"strings"
	"time"

	"./order"
	"./dt"
)

const bestIndent = 2

type emitter struct {
	buf          []byte
	indent       int
	indents      []int
	column       int
	whitespace   bool
	indention    bool
	openEnded    bool
	mappingDepth int
	line         int

	// seq item context for the error case
	inSeqItem bool
	itemIndex int
	err       error
}

func newEmitter() *emitter {
	return &emitter{indent: -1, whitespace: true, indention: true}
}

func (e *emitter) put(b byte) {
	e.buf = append(e.buf, b)
	e.column++
}

func (e *emitter) putBreak() {
	e.buf = append(e.buf, '\n')
	e.column = 0
	e.line++
	e.indention = true
}

func (e *emitter) writeIndent() {
	indent := e.indent
	if indent < 0 {
		indent = 0
	}
	if !e.indention || e.column > indent {
		e.putBreak()
	}
	for e.column < indent {
		e.put(' ')
	}
	e.whitespace = true
	e.indention = true
}

func (e *emitter) writeIndicator(s string, needWhitespace, isWhitespace, isIndention bool) {
	if needWhitespace && !e.whitespace {
		e.put(' ')
	}
	for i := 0; i < len(s); i++ {
		e.put(s[i])
	}
	e.whitespace = isWhitespace
	e.indention = e.indention && isIndention
	e.openEnded = false
}

func (e *emitter) increaseIndent(flow, indentless bool) {
	e.indents = append(e.indents, e.indent)
	if e.indent < 0 {
		if flow {
			e.indent = bestIndent
		} else {
			e.indent = 0
		}
	} else if !indentless {
		e.indent += bestIndent
	}
}

func (e *emitter) restoreIndent() {
	e.indent = e.indents[len(e.indents)-1]
	e.indents = e.indents[:len(e.indents)-1]
}

// encodeYAML converts v to YAML text, validating that the result parses.
func encodeYAML(v interface{}, noInf bool) ([]byte, error) {
	e := newEmitter()
	e.emitNode(v)
	if e.err != nil {
		return nil, e.err
	}
	text := string(e.buf)
	if _, err := parseYAMLText([]byte(text)); err != nil {
		return nil, err
	}
	return e.buf, nil
}

func (e *emitter) emitNode(v interface{}) {
	switch t := v.(type) {
	case nil:
		e.emitScalar("null", stPlain)
	case bool:
		if t {
			e.emitScalar("true", stPlain)
		} else {
			e.emitScalar("false", stPlain)
		}
	case string:
		e.emitString(t)
	case int64:
		e.emitScalar(strconv.FormatInt(t, 10), stPlain)
	case uint64:
		e.emitScalar(strconv.FormatUint(t, 10), stPlain)
	case float64:
		e.emitScalar(formatYAMLFloat(t), stPlain)
	case time.Time:
		e.emitScalar(t.Format(time.RFC3339Nano), stPlain)
	case dt.LocalDate:
		e.emitScalar(t.String(), stPlain)
	case dt.LocalTime:
		e.emitScalar(t.String(), stPlain)
	case dt.LocalDateTime:
		e.emitScalar(t.String(), stPlain)
	case order.MapSlice:
		e.emitMapping(t)
	case []interface{}:
		e.emitSequence(t)
	}
}

func formatYAMLFloat(f float64) string {
	s := strconv.FormatFloat(f, 'g', -1, 64)
	switch s {
	case "+Inf":
		return ".inf"
	case "-Inf":
		return "-.inf"
	case "NaN":
		return ".nan"
	}
	if !strings.ContainsAny(s, ".eE") {
		s += ".0"
	}
	return s
}

func (e *emitter) emitMapping(m order.MapSlice) {
	if len(m) == 0 {
		e.writeIndicator("{}", true, false, false)
		return
	}
	e.increaseIndent(false, false)
	e.mappingDepth++
	for _, it := range m {
		e.writeIndent()
		e.emitKey(it.Key)
		e.writeIndicator(":", false, false, false)
		e.emitValue(it.Val)
	}
	e.mappingDepth--
	e.restoreIndent()
}

func (e *emitter) emitValue(v interface{}) {
	switch t := v.(type) {
	case order.MapSlice:
		e.emitMapping(t)
	case []interface{}:
		e.emitSequence(t)
	default:
		e.emitNode(v)
	}
}

func (e *emitter) emitKey(k interface{}) {
	switch t := k.(type) {
	case string:
		e.emitString(t)
	case nil:
		e.emitScalar("null", stPlain)
	case bool:
		if t {
			e.emitScalar("true", stPlain)
		} else {
			e.emitScalar("false", stPlain)
		}
	case int64:
		e.emitScalar(strconv.FormatInt(t, 10), stPlain)
	case uint64:
		e.emitScalar(strconv.FormatUint(t, 10), stPlain)
	case float64:
		e.emitScalar(formatYAMLFloat(t), stPlain)
	case time.Time:
		e.emitScalar(t.Format(time.RFC3339Nano), stPlain)
	case dt.LocalDate:
		e.emitScalar(t.String(), stPlain)
	case dt.LocalTime:
		e.emitScalar(t.String(), stPlain)
	case dt.LocalDateTime:
		e.emitScalar(t.String(), stPlain)
	case order.MapSlice:
		e.writeIndicator("?", true, false, false)
		e.emitMapping(t)
		e.writeIndicator(":", false, false, false)
	case []interface{}:
		e.writeIndicator("?", true, false, false)
		e.emitSequence(t)
		e.writeIndicator(":", false, false, false)
	}
}

func (e *emitter) emitSequence(s []interface{}) {
	if len(s) == 0 {
		e.writeIndicator("[]", true, false, false)
		return
	}
	e.increaseIndent(false, false)
	for i, item := range s {
		e.writeIndicator("-", true, false, true)
		e.inSeqItem = true
		e.itemIndex = i + 1
		switch t := item.(type) {
		case order.MapSlice:
			e.emitMapping(t)
		case []interface{}:
			e.emitSequence(t)
		default:
			e.emitNode(item)
		}
		e.inSeqItem = false
	}
	e.restoreIndent()
}

// emitString emits a string scalar, choosing the style like the YAML encoder.
func (e *emitter) emitString(s string) {
	canUsePlain := true
	if rtag, _ := resolve("", s); rtag != strTag {
		canUsePlain = false
	}
	if isBase60Float(s) || isOldBool(s) {
		canUsePlain = false
	}
	if s == "<<" {
		e.writeIndicator("!!merge", false, false, false)
		e.emitScalar(s, stPlain)
		return
	}
	var style int
	switch {
	case strings.Contains(s, "\n"):
		style = stLiteral
	case canUsePlain:
		style = stPlain
	default:
		style = stDouble
	}
	e.emitScalar(s, style)
}

func isOldBool(s string) bool {
	switch s {
	case "y", "Y", "yes", "Yes", "YES", "on", "On", "ON",
		"n", "N", "no", "No", "NO", "off", "Off", "OFF":
		return true
	}
	return false
}

var base60Re = regexp.MustCompile(`^[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+(?:\.[0-9_]*)?$`)

func isBase60Float(s string) bool {
	if len(s) == 0 {
		return false
	}
	if s[0] != '+' && s[0] != '-' && (s[0] < '0' || s[0] > '9') {
		return false
	}
	return base60Re.MatchString(s)
}

// scalar analysis (libyaml port)

func isSpaceB(b byte) bool { return b == ' ' }
func isBreakB(b byte) bool { return b == '\n' || b == '\r' }

func analyzeScalar(value string) (multiline, flowPlainOK, blockPlainOK, singleQuotedOK, blockAllowed bool) {
	if len(value) == 0 {
		return false, false, true, true, false
	}
	var blockIndicators, flowIndicators, lineBreaks, specialCharacters, tabCharacters bool
	var leadingSpace, leadingBreak, trailingSpace, trailingBreak, breakSpace, spaceBreak bool
	precededByWhitespace := true
	previousSpace := false
	previousBreak := false
	if len(value) >= 3 && ((value[0] == '-' && value[1] == '-' && value[2] == '-') || (value[0] == '.' && value[1] == '.' && value[2] == '.')) {
		blockIndicators = true
		flowIndicators = true
	}
	for i, w := 0, 0; i < len(value); i += w {
		w = width(value[i])
		followedByWhitespace := i+w >= len(value) || isBlankAt(value, i+w)
		if i == 0 {
			switch value[i] {
			case '#', ',', '[', ']', '{', '}', '&', '*', '!', '|', '>', '\'', '"', '%', '@', '`':
				flowIndicators = true
				blockIndicators = true
			case '?', ':':
				flowIndicators = true
			case '-':
				if followedByWhitespace {
					flowIndicators = true
					blockIndicators = true
				}
			}
		} else {
			switch value[i] {
			case ',', '?', '[', ']', '{', '}':
				flowIndicators = true
			case ':':
				flowIndicators = true
				if followedByWhitespace {
					blockIndicators = true
				}
			case '#':
				if precededByWhitespace {
					flowIndicators = true
					blockIndicators = true
				}
			}
		}
		if value[i] == '\t' {
			tabCharacters = true
		} else if !isPrintable(value, i) {
			specialCharacters = true
		}
		if value[i] == ' ' {
			if i == 0 {
				leadingSpace = true
			}
			if i+w == len(value) {
				trailingSpace = true
			}
			if previousBreak {
				breakSpace = true
			}
			previousSpace = true
			previousBreak = false
		} else if isBreakAt(value, i) {
			lineBreaks = true
			if i == 0 {
				leadingBreak = true
			}
			if i+w == len(value) {
				trailingBreak = true
			}
			if previousSpace {
				spaceBreak = true
			}
			previousSpace = false
			previousBreak = true
		} else {
			previousSpace = false
			previousBreak = false
		}
		precededByWhitespace = isBlankzAt(value, i)
	}
	multiline = lineBreaks
	flowPlainOK = true
	blockPlainOK = true
	singleQuotedOK = true
	blockAllowed = true
	if leadingSpace || leadingBreak || trailingSpace || trailingBreak {
		flowPlainOK = false
		blockPlainOK = false
	}
	if trailingSpace {
		blockAllowed = false
	}
	if breakSpace {
		flowPlainOK = false
		blockPlainOK = false
		singleQuotedOK = false
	}
	if spaceBreak || tabCharacters || specialCharacters {
		flowPlainOK = false
		blockPlainOK = false
		singleQuotedOK = false
	}
	if spaceBreak || specialCharacters {
		blockAllowed = false
	}
	if lineBreaks {
		flowPlainOK = false
		blockPlainOK = false
	}
	if flowIndicators {
		flowPlainOK = false
	}
	if blockIndicators {
		blockPlainOK = false
	}
	return
}

func isBlankAt(s string, i int) bool {
	if i >= len(s) {
		return true
	}
	return s[i] == ' ' || s[i] == '\t'
}

func isBlankzAt(s string, i int) bool {
	if i >= len(s) {
		return true
	}
	c := s[i]
	return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == 0
}

func isBreakAt(s string, i int) bool {
	if i >= len(s) {
		return false
	}
	switch s[i] {
	case '\n', '\r':
		return true
	case 0xC2:
		if i+1 < len(s) && s[i+1] == 0x85 {
			return true
		}
	case 0xE2:
		if i+2 < len(s) && s[i+1] == 0x80 && (s[i+2] == 0xA8 || s[i+2] == 0xA9) {
			return true
		}
	}
	return false
}

func isPrintable(s string, i int) bool {
	if i >= len(s) {
		return false
	}
	b := s[i]
	if b == 0x0A {
		return true
	}
	if b >= 0x20 && b <= 0x7E {
		return true
	}
	if b == 0xC2 && i+1 < len(s) && s[i+1] >= 0xA0 {
		return true
	}
	if b > 0xC2 && b < 0xED {
		return true
	}
	if b == 0xED && i+1 < len(s) && s[i+1] < 0xA0 {
		return true
	}
	if b == 0xEE {
		return true
	}
	if b == 0xEF && i+2 < len(s) {
		if !(s[i+1] == 0xBB && s[i+2] == 0xBF) && !(s[i+1] == 0xBF && (s[i+2] == 0xBE || s[i+2] == 0xBF)) {
			return true
		}
	}
	return false
}

// chooseStyle picks the final scalar style.
func chooseStyle(s string, requested int, simpleKey bool, flowLevel int) int {
	style := requested
	m, _, _, _, _ := analyzeScalar(s)
	if simpleKey && m {
		style = stDouble
	}
	if style == stPlain {
		_, fp, bp, sq, _ := analyzeScalar(s)
		if flowLevel > 0 && !fp || flowLevel == 0 && !bp {
			style = stSingle
		}
		if len(s) == 0 && (flowLevel > 0 || simpleKey) {
			style = stSingle
		}
		if style == stSingle {
			if m {
				style = stDouble
			}
		}
	}
	if style == stLiteral || style == stFolded {
		_, _, _, _, ba := analyzeScalar(s)
		if !ba || flowLevel > 0 || simpleKey {
			style = stDouble
		}
	}
	return style
}

// emitScalar writes a scalar with the chosen style.
func (e *emitter) emitScalar(value string, requested int) {
	style := chooseStyle(value, requested, false, 0)
	switch style {
	case stPlain:
		e.writePlainScalar(value)
	case stSingle:
		e.writeSingleQuoted(value)
	case stDouble:
		e.writeDoubleQuoted(value)
	case stLiteral:
		e.writeLiteralScalar(value)
	case stFolded:
		e.writeLiteralScalar(value)
	}
}

func (e *emitter) writePlainScalar(value string) {
	if !e.whitespace {
		e.put(' ')
	}
	breaks := false
	for i := 0; i < len(value); {
		if value[i] == ' ' {
			e.put(' ')
			i++
		} else if isBreakAt(value, i) {
			e.putBreak()
			e.indention = true
			breaks = true
			i += width(value[i])
		} else {
			if breaks {
				e.writeIndent()
			}
			w := width(value[i])
			for j := 0; j < w && i < len(value); j++ {
				e.put(value[i])
				i++
			}
			e.indention = false
			breaks = false
		}
	}
	e.whitespace = false
}

func (e *emitter) writeSingleQuoted(value string) {
	e.writeIndicator("'", true, false, false)
	breaks := false
	for i := 0; i < len(value); {
		if value[i] == ' ' {
			e.put(' ')
			i++
		} else if isBreakAt(value, i) {
			e.putBreak()
			e.indention = true
			breaks = true
			i += width(value[i])
		} else {
			if breaks {
				e.writeIndent()
			}
			if value[i] == '\'' {
				e.put('\'')
				e.put('\'')
				i++
			} else {
				w := width(value[i])
				for j := 0; j < w && i < len(value); j++ {
					e.put(value[i])
					i++
				}
			}
			e.indention = false
			breaks = false
		}
	}
	e.writeIndicator("'", false, false, false)
	e.whitespace = false
}

var hexUpper = "0123456789ABCDEF"

func (e *emitter) writeDoubleQuoted(value string) {
	e.writeIndicator(`"`, true, false, false)
	for i := 0; i < len(value); {
		b := value[i]
		needEscape := !isPrintable(value, i) || b == '"' || b == '\\' || isBreakAt(value, i)
		if needEscape {
			r, w := decodeRune(value[i:])
			switch r {
			case 0x00:
				e.writeString(`\0`)
			case 0x07:
				e.writeString(`\a`)
			case 0x08:
				e.writeString(`\b`)
			case 0x09:
				e.writeString(`\t`)
			case 0x0A:
				e.writeString(`\n`)
			case 0x0B:
				e.writeString(`\v`)
			case 0x0C:
				e.writeString(`\f`)
			case 0x0D:
				e.writeString(`\r`)
			case 0x1B:
				e.writeString(`\e`)
			case 0x22:
				e.writeString(`\"`)
			case 0x5C:
				e.writeString(`\\`)
			case 0x85:
				e.writeString(`\N`)
			case 0xA0:
				e.writeString(`\_`)
			case 0x2028:
				e.writeString(`\L`)
			case 0x2029:
				e.writeString(`\P`)
			default:
				if r <= 0xFF {
					e.writeString(`\x`)
					e.put(hexUpper[(r>>4)&0xf])
					e.put(hexUpper[r&0xf])
				} else if r <= 0xFFFF {
					e.writeString(`\u`)
					e.writeHex4(r)
				} else {
					e.writeString(`\U`)
					e.writeHex8(r)
				}
			}
			i += w
			continue
		}
		w := width(b)
		for j := 0; j < w && i < len(value); j++ {
			e.put(value[i])
			i++
		}
	}
	e.writeIndicator(`"`, false, false, false)
	e.whitespace = false
}

func decodeRune(s string) (rune int, size int) {
	b := s[0]
	var r int
	var w int
	switch {
	case b&0x80 == 0x00:
		w, r = 1, int(b&0x7F)
	case b&0xE0 == 0xC0:
		w, r = 2, int(b&0x1F)
	case b&0xF0 == 0xE0:
		w, r = 3, int(b&0x0F)
	case b&0xF8 == 0xF0:
		w, r = 4, int(b&0x07)
	default:
		w, r = 1, int(b)
	}
	for k := 1; k < w && k < len(s); k++ {
		r = (r << 6) + (int(s[k]) & 0x3F)
	}
	return r, w
}

func (e *emitter) writeHex4(r int) {
	for i := 3; i >= 0; i-- {
		e.put(hexUpper[(r>>(4*i))&0xf])
	}
}

func (e *emitter) writeHex8(r int) {
	for i := 7; i >= 0; i-- {
		e.put(hexUpper[(r>>(4*i))&0xf])
	}
}

func (e *emitter) writeString(s string) {
	for i := 0; i < len(s); i++ {
		e.put(s[i])
	}
}

// writeLiteralScalar writes a literal block scalar, applying yj's trimming quirk.
func (e *emitter) writeLiteralScalar(value string) {
	t := e.mappingDepth + 1
	k := 0
	for k < len(value) && value[k] == '\n' {
		k++
	}
	content := value
	if k > 0 {
		n := k
		if n > t {
			n = t
		}
		content = value[n:]
	}
	hintOK := t-1 < len(value) && (isSpaceB(value[t-1]) || isBreakB(value[t-1]))
	if e.inSeqItem && e.mappingDepth >= 1 {
		// yj emits invalid YAML for block scalars as sequence items nested in mappings
		e.err = &seqIndicatorError{line: e.itemIndex}
		return
	}
	if len(content) == 0 && !hintOK {
		e.emitScalar("", stDouble)
		return
	}
	e.writeIndicator("|", true, false, false)
	if hintOK {
		e.writeIndicator(strconv.Itoa(bestIndent), false, false, false)
	}
	e.writeChompHint(value)
	e.putBreak()
	e.indention = true
	e.whitespace = true
	breaks := true
	for i := 0; i < len(content); {
		if isBreakAt(content, i) {
			e.putBreak()
			i += width(content[i])
			e.indention = true
			breaks = true
		} else {
			if breaks {
				e.writeIndent()
			}
			w := width(content[i])
			for j := 0; j < w && i < len(content); j++ {
				e.put(content[i])
				i++
			}
			e.indention = false
			breaks = false
		}
	}
}

// writeChompHint computes the chomping hint from the original value.
func (e *emitter) writeChompHint(value string) {
	var chomp string
	if len(value) == 0 {
		chomp = "-"
	} else {
		i := len(value) - 1
		for i > 0 && value[i]&0xC0 == 0x80 {
			i--
		}
		if !isBreakAt(value, i) {
			chomp = "-"
		} else if i == 0 {
			chomp = "+"
			e.openEnded = true
		} else {
			i--
			for i > 0 && value[i]&0xC0 == 0x80 {
				i--
			}
			if isBreakAt(value, i) {
				chomp = "+"
				e.openEnded = true
			}
		}
	}
	if chomp != "" {
		e.writeIndicator(chomp, false, false, false)
	}
}

type seqIndicatorError struct{ line int }

func (s *seqIndicatorError) Error() string {
	return "yaml: line " + strconv.Itoa(s.line) + ": did not find expected '-' indicator"
}
EOF
