{"command": "cat > /workspace/src/tomlp.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"

	"./order"
	"./dt"
)

type tomlErr struct {
	line    int
	lastKey string
	msg     string
}

func (e *tomlErr) Error() string {
	if e.lastKey != "" {
		return fmt.Sprintf("toml: line %d (last key \"%s\"): %s", e.line, e.lastKey, e.msg)
	}
	return fmt.Sprintf("toml: line %d: %s", e.line, e.msg)
}

type tparser struct {
	src     []byte
	pos     int
	line    int // 1-based
	lastKey string
	root    order.MapSlice
}

func (p *tparser) err(msg string) error {
	return &tomlErr{line: p.line, lastKey: p.lastKey, msg: msg}
}

func (p *tparser) errNoKey(msg string) error {
	return &tomlErr{line: p.line, lastKey: "", msg: msg}
}

func (p *tparser) peek() byte {
	if p.pos >= len(p.src) {
		return 0
	}
	return p.src[p.pos]
}

func (p *tparser) peekAt(n int) byte {
	if p.pos+n >= len(p.src) {
		return 0
	}
	return p.src[p.pos+n]
}

func (p *tparser) advance() {
	if p.pos < len(p.src) {
		if p.src[p.pos] == '\n' {
			p.line++
		}
		p.pos++
	}
}

func (p *tparser) skipSpaces() {
	for !p.eof() {
		c := p.peek()
		if c == ' ' || c == '\t' {
			p.advance()
		} else {
			break
		}
	}
}

func (p *tparser) eof() bool { return p.pos >= len(p.src) }

func (p *tparser) skipComment() {
	if p.peek() == '#' {
		for !p.eof() && p.peek() != '\n' {
			p.advance()
		}
	}
}

func (p *tparser) skipEOL() error {
	p.skipComment()
	if p.eof() {
		return nil
	}
	if p.peek() == '\n' {
		p.advance()
		return nil
	}
	if p.peek() == '\r' && p.peekAt(1) == '\n' {
		p.advance()
		p.advance()
		return nil
	}
	return p.errNoKey(fmt.Sprintf("expected a top-level item to end with a newline, comment, or EOF, but got '%c' instead", p.peek()))
}

// parseTOML parses TOML into an ordered map.
func parseTOML(data []byte) (interface{}, error) {
	p := &tparser{src: data, line: 1, root: order.MapSlice{}}
	if err := p.parse(); err != nil {
		return nil, err
	}
	return p.root, nil
}

func (p *tparser) parse() error {
	for {
		p.skipSpaces()
		if p.eof() {
			return nil
		}
		c := p.peek()
		if c == '\n' {
			p.advance()
			continue
		}
		if c == '\r' && p.peekAt(1) == '\n' {
			p.advance()
			p.advance()
			continue
		}
		if c == '#' {
			p.skipComment()
			continue
		}
		if c == '[' {
			if err := p.parseTableHeader(); err != nil {
				return err
			}
			continue
		}
		// key = value
		if err := p.parseKeyVal(p.root); err != nil {
			return err
		}
		if err := p.skipEOL(); err != nil {
			return err
		}
	}
}

func (p *tparser) parseTableHeader() error {
	p.advance() // [
	arrayOfTables := false
	if p.peek() == '[' {
		arrayOfTables = true
		p.advance()
	}
	p.skipSpaces()
	if p.peek() == ']' {
		return p.errNoKey("unexpected end of table name (table names cannot be empty)")
	}
	parts, err := p.parseKeyPath()
	if err != nil {
		return err
	}
	p.skipSpaces()
	if p.peek() != ']' {
		return p.errNoKey(fmt.Sprintf("expected ']', but got '%c' instead", p.peek()))
	}
	p.advance()
	if arrayOfTables {
		if p.peek() != ']' {
			return p.errNoKey("expected ']'")
		}
		p.advance()
	}
	return p.enterTable(parts, arrayOfTables)
}

func (p *tparser) parseKeyPath() ([]string, error) {
	var parts []string
	for {
		p.skipSpaces()
		part, err := p.parseKeyPart()
		if err != nil {
			return nil, err
		}
		parts = append(parts, part)
		p.skipSpaces()
		c := p.peek()
		if c == '.' {
			p.advance()
			continue
		}
		return parts, nil
	}
}

func (p *tparser) parseKeyPart() (string, error) {
	c := p.peek()
	if c == '"' {
		return p.parseBasicString(false)
	}
	if c == '\'' {
		return p.parseLiteralString(false)
	}
	start := p.pos
	for !p.eof() {
		c := p.peek()
		if c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || c == '-' {
			p.advance()
			continue
		}
		break
	}
	if p.pos == start {
		if p.peek() == '=' {
			return "", p.errNoKey("unexpected '=': key name appears blank")
		}
		return "", p.errNoKey(fmt.Sprintf("unexpected key name or end of line"))
	}
	return string(p.src[start:p.pos]), nil
}

// getOrCreate walks/creates the nested tables for parts.
func (p *tparser) getOrCreate(cur order.MapSlice, parts []string, i int, arrayOfTables bool) (order.MapSlice, error) {
	if i == len(parts)-1 {
		return cur, nil
	}
	// handled by caller
	return cur, nil
}

func (p *tparser) enterTable(parts []string, arrayOfTables bool) error {
	cur := p.root
	var last *order.MapItem
	for i, part := range parts {
		isLast := i == len(parts)-1
		idx := -1
		for j := range cur {
			if cur[j].Key == part {
				idx = j
				break
			}
		}
		if idx < 0 {
			if isLast {
				if arrayOfTables {
					v := []interface{}{}
					m := order.MapSlice{}
					v = append(v, m)
					cur = append(cur, order.MapItem{Key: part, Val: v})
					last = &cur[len(cur)-1]
					cur = m
				} else {
					m := order.MapSlice{}
					cur = append(cur, order.MapItem{Key: part, Val: m})
					last = &cur[len(cur)-1]
					cur = m
				}
			} else {
				m := order.MapSlice{}
				cur = append(cur, order.MapItem{Key: part, Val: m})
				last = &cur[len(cur)-1]
				cur = m
			}
			continue
		}
		switch t := cur[idx].Val.(type) {
		case order.MapSlice:
			cur = t
		case []interface{}:
			// array of tables: use the last element
			if len(t) > 0 {
				if ms, ok := t[len(t)-1].(order.MapSlice); ok {
					if isLast && !arrayOfTables {
						return p.errNoKey(fmt.Sprintf("Key '%s' has already been defined.", strings.Join(parts[:i+1], ".")))
					}
					cur = ms
				} else {
					return p.errNoKey(fmt.Sprintf("Key '%s' has already been defined.", strings.Join(parts[:i+1], ".")))
				}
			} else {
				m := order.MapSlice{}
				t = append(t, m)
				cur[idx].Val = t
				cur = m
			}
		default:
			return p.errNoKey(fmt.Sprintf("Key '%s' has already been defined.", strings.Join(parts[:i+1], ".")))
		}
	}
	return nil
}

func (p *tparser) parseKeyVal(cur order.MapSlice) error {
	parts, err := p.parseKeyPath()
	if err != nil {
		return err
	}
	p.lastKey = strings.Join(parts, ".")
	p.skipSpaces()
	if p.peek() != '=' {
		return p.errNoKey(fmt.Sprintf("expected '.' or '=', but got '%c' instead", p.peek()))
	}
	p.advance()
	p.skipSpaces()
	val, err := p.parseValue()
	if err != nil {
		return err
	}
	// navigate to the parent of the last part
	target := cur
	for i := 0; i < len(parts)-1; i++ {
		idx := -1
		for j := range target {
			if target[j].Key == parts[i] {
				idx = j
				break
			}
		}
		if idx < 0 {
			m := order.MapSlice{}
			target = append(target, order.MapItem{Key: parts[i], Val: m})
			idx = len(target) - 1
		}
		t, ok := target[idx].Val.(order.MapSlice)
		if !ok {
			return p.err(fmt.Sprintf("Key '%s' has already been defined.", strings.Join(parts[:i+1], ".")))
		}
		target = t
	}
	k := parts[len(parts)-1]
	for j := range target {
		if target[j].Key == k {
			return p.err(fmt.Sprintf("Key '%s' has already been defined.", k))
		}
	}
	target = append(target, order.MapItem{Key: k, Val: val})
	// write back
	if len(parts) == 1 {
		if cur != nil {
			// append to cur
			*curPtr(cur) = target
		}
	}
	return nil
}

func curPtr(cur order.MapSlice) *order.MapSlice {
	return &cur
}
EOF
echo ok"}

